export function SpringScaleIn({
  text,
  staggerDelay = 3,
  scaleFrom = 0.7,
  fontSize = 72,
  color = "#171717",
  fontWeight = 600,
  speed = 1,
  className,
}: SpringScaleInProps) {
  const frame = useCurrentFrame() * speed;

  const words = text.split(" ");
  const wordDurationFrames = 11;
  const easing = Easing.bezier(0.34, 1.56, 0.64, 1);

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
