import { Easing, interpolate, useCurrentFrame } from "remotion";

export interface SqueezeInProps {
  text: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  stagger?: number;
  squeeze?: number;
  speed?: number;
  className?: string;
}

const SQUEEZE_FRAMES = 16;

export function squeezeInLength(text: string, stagger = 3): number {
  const chars = Array.from(text);
  if (chars.length === 0) return 0;
  return chars.length * stagger + SQUEEZE_FRAMES;
}

const squeezeEasing = Easing.out(Easing.cubic);

export function SqueezeIn({
  text,
  fontSize = 72,
  color = "#171717",
  fontWeight = 400,
  stagger = 3,
  squeeze = 0.03,
  speed = 1,
  className,
}: SqueezeInProps) {
  const frame = useCurrentFrame() * speed;

  const chars = Array.from(text);
  const lastRevealAt = chars.length * stagger;

  const squeezeProgress = interpolate(
    frame,
    [lastRevealAt, lastRevealAt + SQUEEZE_FRAMES],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: squeezeEasing,
    },
  );

  const gap = squeeze * fontSize * (1 - squeezeProgress);
  const wipe = interpolate(frame, [0, lastRevealAt], [100, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const anchorX =
    (-squeeze * fontSize * squeezeProgress * (chars.length - 1)) / 2;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        whiteSpace: "nowrap",
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          translate: `${anchorX}px 0`,
          clipPath: `inset(-0.2em ${wipe}% -0.25em -0.1em)`,
          fontSize,
          fontWeight,
          color,
          letterSpacing: "-0.02em",
          lineHeight: 1.1,
          fontFamily:
            "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
        }}
      >
        {chars.map((char, j) => (
          <span
            key={j}
            style={{
              display: "inline-block",
              whiteSpace: "pre",
              marginRight: j < chars.length - 1 ? gap : undefined,
            }}
          >
            {char}
          </span>
        ))}
      </span>
    </div>
  );
}

"use client";

import { interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";

export interface FogRiseProps {
  text: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  stagger?: number;
  blur?: number;
  tilt?: number;
  depth?: number;
  lift?: number;
  drift?: number;
  exitAt?: number;
  exitAccel?: number;
  mass?: number;
  stiffness?: number;
  damping?: number;
  spreadGap?: number;
  tracking?: number;
  resolveFrames?: number;
  fadeFrames?: number;
  speed?: number;
  className?: string;
}

export function fogRiseLength(
  text: string,
  stagger = 5,
  resolveFrames = 22,
): number {
  const chars = Array.from(text);
  if (chars.length === 0) return 0;
  const center = (chars.length - 1) / 2;
  const maxRing = Math.floor(center);
  return maxRing * stagger + resolveFrames;
}

export function FogRise({
  text,
  fontSize = 304,
  color = "#004CFF",
  fontWeight = 400,
  stagger = 5,
  blur = 0.17,
  tilt = 55,
  depth = 5,
  lift = 0.85,
  drift = 0.005,
  exitAt = 60,
  exitAccel = 0.04,
  mass = 1.3,
  stiffness = 60,
  damping = 13,
  spreadGap = 0.07,
  tracking = -0.07,
  resolveFrames = 22,
  fadeFrames = 18,
  speed = 1,
  className,
}: FogRiseProps) {
  const frame = useCurrentFrame() * speed;
  const { fps } = useVideoConfig();

  const chars = Array.from(text);
  const center = (chars.length - 1) / 2;
  const minRing = chars.length % 2 === 0 ? 0.5 : 0;
  const maxRing = Math.floor(center);

  const converge = spring({
    frame,
    fps,
    config: { mass, stiffness, damping },
  });
  const angle = tilt * (1 - converge);
  const liftY = lift * fontSize * (1 - converge);
  const driftY = drift * fontSize * frame;
  const exitT = exitAt > 0 ? Math.max(frame - exitAt, 0) : 0;
  const exitY = 0.5 * exitAccel * exitT * exitT * fontSize;
  const gap = spreadGap * fontSize * (1 - converge);

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "flex-end",
        justifyContent: "center",
        paddingBottom: "6%",
        whiteSpace: "nowrap",
        perspective: `${depth * fontSize}px`,
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          transform: `translateY(${liftY - driftY - exitY}px) rotateX(${-angle}deg)`,
          transformOrigin: "50% 100%",
          fontSize,
          fontWeight,
          color,
          letterSpacing: `${tracking}em`,
          lineHeight: 1.15,
          fontFamily:
            "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
        }}
      >
        {chars.map((char, j) => {
          const ring = Math.abs(j - center) - minRing;
          const startAt = ring * stagger;

          const opacity = interpolate(
            frame,
            [startAt, startAt + fadeFrames],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
          );

          const charBlur =
            blur *
            fontSize *
            interpolate(frame, [0, maxRing * stagger + resolveFrames], [1, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });

          return (
            <span
              key={j}
              style={{
                display: "inline-block",
                whiteSpace: "pre",
                marginRight: j < chars.length - 1 ? gap : undefined,
                opacity,
                filter: charBlur > 0.05 ? `blur(${charBlur}px)` : undefined,
              }}
            >
              {char}
            </span>
          );
        })}
      </span>
    </div>
  );
}

"use client";

import { Easing, interpolate, useCurrentFrame } from "remotion";

export interface CaretSwapProps {
  fromText: string;
  toText: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  caretColor?: string;
  caretColorEnd?: string;
  swapAt?: number;
  typeSpeed?: number;
  speed?: number;
  className?: string;
}

const CARET_LEAD = 7;
const EXPAND_FRAMES = 6;
const COLLAPSE_FRAMES = 7;
const IDLE_FRAMES = 7;
const BLINK_FRAMES = 8;
const CARET_WIDTH_EM = 0.08;
const CARET_HEIGHT_EM = 1.1;
const CARET_GAP_EM = 0.06;
const CHAR_WIDTH_EM = 0.52;
const TYPE_ACCEL = 0.96;

function typeElapsed(count: number, typeSpeed: number): number {
  return (typeSpeed * (1 - TYPE_ACCEL ** count)) / (1 - TYPE_ACCEL);
}

export function caretSwapLength(
  toText: string,
  swapAt = 20,
  typeSpeed = 1,
): number {
  return Math.ceil(
    swapAt +
      EXPAND_FRAMES +
      COLLAPSE_FRAMES +
      IDLE_FRAMES +
      typeElapsed(Array.from(toText).length, typeSpeed),
  );
}

const expandEasing = Easing.bezier(0.6, 0, 0.8, 0.4);
const collapseEasing = Easing.bezier(0.2, 0.7, 0.3, 1);

export function CaretSwap({
  fromText,
  toText,
  fontSize = 72,
  color = "#171717",
  fontWeight = 400,
  caretColor = "#FF4DAA",
  caretColorEnd = "#8A5CF6",
  swapAt = 20,
  typeSpeed = 1,
  speed = 1,
  className,
}: CaretSwapProps) {
  const frame = useCurrentFrame() * speed;

  const toChars = Array.from(toText);
  const caretWidth = CARET_WIDTH_EM * fontSize;
  const caretHeight = CARET_HEIGHT_EM * fontSize;

  const caretVisibleAt = Math.max(swapAt - CARET_LEAD, 0);
  const expandEnd = swapAt + EXPAND_FRAMES;
  const collapseEnd = expandEnd + COLLAPSE_FRAMES;
  const typeStart = collapseEnd + IDLE_FRAMES;
  const typeEnd = typeStart + typeElapsed(toChars.length, typeSpeed);

  const expand = interpolate(frame, [swapAt, expandEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: expandEasing,
  });
  const collapse = interpolate(frame, [expandEnd, collapseEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: collapseEasing,
  });

  const typing = frame >= typeStart;
  let typedCount = 0;
  if (typing) {
    while (
      typedCount < toChars.length &&
      typeElapsed(typedCount, typeSpeed) <= frame - typeStart
    ) {
      typedCount++;
    }
  }
  const typed = toChars.slice(0, typedCount).join("");

  const anchorWidthEm =
    Array.from(fromText).length * CHAR_WIDTH_EM + CARET_WIDTH_EM + CARET_GAP_EM;
  const targetShiftEm = (anchorWidthEm - toChars.length * CHAR_WIDTH_EM) / 2;
  const typeProgress = toChars.length > 0 ? typedCount / toChars.length : 0;
  const typedShift = targetShiftEm * typeProgress * fontSize;

  const blinkOff =
    frame >= typeEnd + BLINK_FRAMES &&
    Math.floor((frame - typeEnd) / BLINK_FRAMES) % 2 === 1;

  const caretStyle = {
    background: `linear-gradient(180deg, ${caretColor}, ${caretColorEnd})`,
    borderRadius: fontSize * 0.03,
  };

  const overlayWidth =
    frame < expandEnd
      ? `calc(${(expand * 100).toFixed(3)}% + ${((1 - expand) * caretWidth).toFixed(2)}px)`
      : `calc(${((1 - collapse) * 100).toFixed(3)}% + ${(collapse * caretWidth).toFixed(2)}px)`;

  const tailSolidStop =
    frame < expandEnd ? 100 - 90 * expand : 10 + 90 * collapse;
  const tailMask =
    frame >= swapAt
      ? `linear-gradient(90deg, black ${tailSolidStop.toFixed(1)}%, transparent 100%)`
      : undefined;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        whiteSpace: "nowrap",
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          position: "relative",
          display: "inline-flex",
          alignItems: "center",
          fontSize,
          fontWeight,
          color,
          letterSpacing: "-0.02em",
          lineHeight: 1.15,
          fontFamily:
            "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
        }}
      >
        <span
          style={{
            display: "inline-block",
            whiteSpace: "pre",
            visibility: frame < expandEnd ? "visible" : "hidden",
          }}
        >
          {fromText}
        </span>
        <span
          aria-hidden
          style={{
            ...caretStyle,
            display: "inline-block",
            flexShrink: 0,
            width: caretWidth,
            height: caretHeight,
            marginLeft: CARET_GAP_EM * fontSize,
            visibility: "hidden",
          }}
        />
        {!typing && (
          <span
            aria-hidden
            style={{
              ...caretStyle,
              position: "absolute",
              top: "50%",
              transform: "translateY(-50%)",
              height: caretHeight,
              ...(frame < swapAt
                ? { right: 0, width: caretWidth }
                : frame < expandEnd
                  ? { right: 0, width: overlayWidth }
                  : { left: 0, width: overlayWidth }),
              WebkitMaskImage: tailMask,
              maskImage: tailMask,
              opacity: frame >= caretVisibleAt ? 1 : 0,
            }}
          />
        )}
        {typing && (
          <span
            style={{
              position: "absolute",
              left: 0,
              top: "50%",
              transform: `translate(${typedShift.toFixed(1)}px, -50%)`,
              display: "inline-flex",
              alignItems: "center",
              whiteSpace: "pre",
            }}
          >
            <span style={{ display: "inline-block", whiteSpace: "pre" }}>
              {typed}
            </span>
            <span
              aria-hidden
              style={{
                ...caretStyle,
                display: "inline-block",
                flexShrink: 0,
                width: caretWidth,
                height: caretHeight,
                marginLeft: CARET_GAP_EM * fontSize,
                opacity: blinkOff ? 0 : 1,
              }}
            />
          </span>
        )}
      </span>
    </div>
  );
}

"use client";

import { Easing, interpolate, useCurrentFrame } from "remotion";

export interface ZoomWordsProps {
  text: string;
  fontSize?: number;
  zoom?: number;
  color?: string;
  fontWeight?: number;
  wordGap?: number;
  anchor?: number;
  blur?: number;
  blurFrames?: number;
  speed?: number;
  className?: string;
}

const CHAR_WIDTH_EM = 0.52;
const SPACE_WIDTH_EM = 0.3;
const WORD_BLUR_EM = 0.05;
const phraseEasing = Easing.bezier(0.5, 0, 0.7, 0.7);
const FADE_EARLY = 0.5;
const FADE_SLOTS = 2;

function smoothstep(t: number): number {
  const x = Math.min(Math.max(t, 0), 1);
  return x * x * (3 - 2 * x);
}
const WORD_SHIFT_X_EM = 0.16;
const WORD_SHIFT_Y_EM = 0.12;

function wordWidthEm(word: string): number {
  return Array.from(word).length * CHAR_WIDTH_EM + SPACE_WIDTH_EM;
}

export function zoomWordsLength(text: string, wordGap = 12): number {
  const words = text.trim().split(/\s+/).filter(Boolean);
  return words.length * wordGap;
}

export function ZoomWords({
  text,
  fontSize = 64,
  zoom = 2.2,
  color = "#cfc2ff",
  fontWeight = 400,
  wordGap = 12,
  anchor = 0.5,
  blur = 0.04,
  blurFrames = 60,
  speed = 1,
  className,
}: ZoomWordsProps) {
  const frame = useCurrentFrame() * speed;

  const words = text.trim().split(/\s+/).filter(Boolean);

  const phraseFrames = words.length * wordGap;
  const wordProgress =
    words.length *
    interpolate(frame, [0, phraseFrames], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: phraseEasing,
    });

  const totalEm = words.reduce((sum, w) => sum + wordWidthEm(w), 0);
  const firstHalfEm = words.length > 0 ? wordWidthEm(words[0]) / 2 : 0;
  const lastHalfEm =
    words.length > 0 ? wordWidthEm(words[words.length - 1]) / 2 : 0;
  let revealedEm = 0;
  for (let i = 0; i < words.length; i++) {
    revealedEm +=
      wordWidthEm(words[i]) *
      smoothstep((wordProgress - i + FADE_EARLY) / FADE_SLOTS);
  }
  const travelMax = Math.max(totalEm - lastHalfEm - firstHalfEm, 0.001);
  const raw = Math.min(Math.max(revealedEm, 0), travelMax);
  const cameraEm = firstHalfEm + travelMax * smoothstep(raw / travelMax);
  const cameraPct = totalEm > 0 ? (cameraEm / totalEm) * 100 : 0;

  const blurNow =
    blur *
    fontSize *
    zoom *
    interpolate(frame, [0, blurFrames], [1, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        background: "transparent",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          scale: `${zoom}`,
          filter: blurNow > 0.05 ? `blur(${blurNow}px)` : undefined,
        }}
      >
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: `${anchor * 100}%`,
            transform: "translateY(-50%)",
            whiteSpace: "pre",
          }}
        >
          <span
            className={className}
            style={{
              display: "inline-flex",
              alignItems: "baseline",
              transform: `translateX(-${cameraPct.toFixed(3)}%)`,
              fontSize,
              fontWeight,
              color,
              letterSpacing: "-0.02em",
              lineHeight: 1.15,
              whiteSpace: "pre",
              fontFamily:
                "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
            }}
          >
            {words.map((word, i) => {
              const p = smoothstep(
                (wordProgress - i + FADE_EARLY) / FADE_SLOTS,
              );
              const opacity = smoothstep(p * 1.2);
              const wordBlur = WORD_BLUR_EM * fontSize * (1 - p);
              const arrive = 1 - smoothstep(p * 1.6);
              return (
                <span
                  key={i}
                  style={{
                    display: "inline-block",
                    whiteSpace: "pre",
                    opacity,
                    filter: wordBlur > 0.05 ? `blur(${wordBlur}px)` : undefined,
                    translate: `${(WORD_SHIFT_X_EM * fontSize * arrive).toFixed(1)}px ${(WORD_SHIFT_Y_EM * fontSize * arrive).toFixed(1)}px`,
                  }}
                >
                  {word}
                  {i < words.length - 1 && " "}
                </span>
              );
            })}
          </span>
        </div>
      </div>
    </div>
  );
}

"use client";

import { Easing, interpolate, useCurrentFrame } from "remotion";

export interface CenteredWordBuildProps {
  text: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  wordGap?: number;
  accel?: number;
  rise?: number;
  zoomStep?: number;
  settleFrames?: number;
  exitAt?: number;
  exitFrames?: number;
  speed?: number;
  className?: string;
}

function revealFrame(index: number, wordGap: number, accel: number): number {
  let frame = 0;

  for (let step = 1; step <= index; step++) {
    // Establish two even beats before tightening the cadence.
    frame += wordGap * accel ** Math.max(step - 2, 0);
  }

  return Math.round(frame);
}

export function centeredWordBuildLength(
  text: string,
  wordGap = 11,
  accel = 0.75,
  settleFrames = 9,
  exitAt = 51,
  exitFrames = 12,
): number {
  const words = text.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return 0;

  const lastReveal = revealFrame(words.length - 1, wordGap, accel);
  return Math.max(lastReveal + settleFrames, exitAt + exitFrames);
}

const settleEasing = Easing.bezier(0.16, 1, 0.3, 1);

export function CenteredWordBuild({
  text,
  fontSize = 52,
  color = "#fff3df",
  fontWeight = 400,
  wordGap = 11,
  accel = 0.75,
  rise = 0.18,
  zoomStep = 0.035,
  settleFrames = 9,
  exitAt = 51,
  exitFrames = 12,
  speed = 1,
  className,
}: CenteredWordBuildProps) {
  const frame = useCurrentFrame() * speed;
  const words = text.trim().split(/\s+/).filter(Boolean);

  if (words.length === 0) return null;

  const visibleCount = words.filter(
    (_, index) => frame >= revealFrame(index, wordGap, accel),
  ).length;
  let cameraScale = 1;
  for (let index = 1; index < visibleCount; index++) {
    const revealAt = revealFrame(index, wordGap, accel);
    cameraScale +=
      zoomStep *
      interpolate(
        frame,
        [revealAt, revealAt + Math.max(settleFrames, 0.001)],
        [0, 1],
        {
          easing: settleEasing,
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        },
      );
  }
  const exitProgress = interpolate(
    frame,
    [exitAt, exitAt + Math.max(exitFrames, 0.001)],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );
  const fadeStart = -35 + exitProgress * 135;
  const fadeEnd = fadeStart + 35;
  const exitMask = `linear-gradient(90deg, transparent ${fadeStart}%, black ${fadeEnd}%)`;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          color,
          display: "inline-block",
          fontFamily:
            "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
          fontSize,
          fontWeight,
          letterSpacing: "-0.02em",
          lineHeight: 1.1,
          whiteSpace: "nowrap",
          scale: `${cameraScale}`,
          opacity: exitProgress >= 1 ? 0 : 1,
          maskImage: exitProgress > 0 ? exitMask : undefined,
          WebkitMaskImage: exitProgress > 0 ? exitMask : undefined,
          maskRepeat: "no-repeat",
          WebkitMaskRepeat: "no-repeat",
        }}
      >
        {words.slice(0, visibleCount).map((word, index) => {
          const revealAt = revealFrame(index, wordGap, accel);
          const y = interpolate(
            frame,
            [revealAt, revealAt + Math.max(settleFrames, 0.001)],
            [rise * fontSize, 0],
            {
              easing: settleEasing,
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            },
          );

          return (
            <span
              key={index}
              style={{
                display: "inline-block",
                marginLeft: index > 0 ? "0.25em" : undefined,
                translate: `0 ${y}px`,
              }}
            >
              {word}
            </span>
          );
        })}
      </span>
    </div>
  );
}

"use client";

import { Easing, interpolate, useCurrentFrame } from "remotion";

export interface InlinePillTakeoverProps {
  before: string;
  insert: string;
  after: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  pillWidth?: number;
  pillColor?: string;
  pillTextColor?: string;
  expandFrames?: number;
  pillRevealHeightScale?: number;
  pillGrowAt?: number;
  pillGrowFrames?: number;
  pillGrowWidthScale?: number;
  pillGrowHeightScale?: number;
  outerExitFrames?: number;
  takeoverAt?: number;
  takeoverScale?: number;
  blur?: number;
  speed?: number;
  className?: string;
}

const PRE_CUT_FRAMES = 12;
const TAKEOVER_SETTLE_FRAMES = 6;
const PRE_CUT_CAMERA_SCALE = 1.25;
const CAMERA_CUT_ENTRY_PROGRESS = 0.86;
const expandEasing = Easing.out(Easing.quad);
const pillGrowEasing = Easing.inOut(Easing.quad);
const fadeEasing = Easing.in(Easing.cubic);
const preCutEasing = Easing.out(Easing.quad);
const takeoverSettleEasing = Easing.out(Easing.cubic);

export function InlinePillTakeover({
  before,
  insert,
  after,
  fontSize = 52,
  color = "#fff3df",
  fontWeight = 400,
  pillWidth = 260,
  pillColor = "#fffaf0",
  pillTextColor = "#1c1210",
  expandFrames = 12,
  pillRevealHeightScale = 0.35,
  pillGrowAt = 12,
  pillGrowFrames = 24,
  pillGrowWidthScale = 1.08,
  pillGrowHeightScale = 1.16,
  outerExitFrames = 18,
  takeoverAt = 12,
  takeoverScale = 2.15,
  blur = 12,
  speed = 1,
  className,
}: InlinePillTakeoverProps) {
  const frame = useCurrentFrame() * speed;
  const safeExpandFrames = Math.max(expandFrames, 0.001);
  const pillGrowEnd = pillGrowAt + Math.max(pillGrowFrames, 0.001);
  const outerExitEnd = Math.max(outerExitFrames, 2.001);
  const dashWidth = fontSize * 0.72;
  const pillHeight = fontSize * 1.22;
  const cutAt = takeoverAt + PRE_CUT_FRAMES;
  const cutEntryScale = takeoverScale * CAMERA_CUT_ENTRY_PROGRESS;

  const expand = interpolate(frame, [0, safeExpandFrames], [0, 1], {
    easing: expandEasing,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const pillGrowProgress = interpolate(
    frame,
    [pillGrowAt, pillGrowEnd],
    [0, 1],
    {
      easing: pillGrowEasing,
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );
  const outerExit = interpolate(frame, [2, outerExitEnd], [0, 1], {
    easing: fadeEasing,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const pillTextOpacity = frame >= 3 ? 1 : 0;
  const preCutCameraScale = interpolate(
    frame,
    [takeoverAt, cutAt - 1],
    [1, PRE_CUT_CAMERA_SCALE],
    {
      easing: preCutEasing,
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );
  const postCutCameraScale = interpolate(
    frame,
    [cutAt, cutAt + TAKEOVER_SETTLE_FRAMES],
    [cutEntryScale, takeoverScale],
    {
      easing: takeoverSettleEasing,
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );
  const cameraScale = frame < cutAt ? preCutCameraScale : postCutCameraScale;
  const revealedPillWidth = dashWidth + (pillWidth - dashWidth) * expand;
  const revealedPillHeight =
    pillHeight * (pillRevealHeightScale + (1 - pillRevealHeightScale) * expand);
  const pillWidthGrow = 1 + (pillGrowWidthScale - 1) * pillGrowProgress;
  const pillHeightGrow = 1 + (pillGrowHeightScale - 1) * pillGrowProgress;
  const animatedPillWidth = revealedPillWidth * pillWidthGrow;
  const animatedPillHeight = revealedPillHeight * pillHeightGrow;

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
        background: "transparent",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${cameraScale})`,
          transformOrigin: "center",
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            width: "100%",
            gap: `${fontSize * 0.16}px`,
            whiteSpace: "nowrap",
            fontFamily:
              "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
            fontSize,
            fontWeight,
            letterSpacing: "-0.02em",
            lineHeight: 1,
          }}
        >
          <span
            style={{
              flex: 1,
              textAlign: "right",
              color,
              opacity: 1 - outerExit,
              filter: outerExit > 0 ? `blur(${blur * outerExit}px)` : undefined,
            }}
          >
            {before}
          </span>

          <span
            style={{
              position: "relative",
              display: "inline-block",
              flexShrink: 0,
              width: animatedPillWidth,
              height: animatedPillHeight,
              overflow: "hidden",
              borderRadius: animatedPillHeight / 2,
              background: pillColor,
              color: pillTextColor,
            }}
          >
            <span
              style={{
                position: "absolute",
                top: "50%",
                left: "50%",
                translate: "-50% -50%",
                fontSize: fontSize * 0.84,
                opacity: pillTextOpacity,
                whiteSpace: "nowrap",
              }}
            >
              {insert}
            </span>
          </span>

          <span
            style={{
              flex: 1,
              textAlign: "left",
              color,
              opacity: 1 - outerExit,
              filter: outerExit > 0 ? `blur(${blur * outerExit}px)` : undefined,
            }}
          >
            {after}
          </span>
        </div>
      </div>
    </div>
  );
}

