import type { CSSProperties } from "react";
import { Easing, interpolate, useCurrentFrame } from "remotion";

export interface TypedSplitWipeProps {
  prefix: string;
  anchor: string;
  suffix: string;
  typeFrames?: number;
  exitAt?: number;
  exitFrames?: number;
  wordStagger?: number;
  anchorShift?: number;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  speed?: number;
  className?: string;
}

const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};
const wipeEasing = Easing.inOut(Easing.quad);

export function getTypedSplitWipeText(
  text: string,
  frame: number,
  typeFrames: number,
) {
  const characters = Array.from(text);
  const typedLength = interpolate(
    frame,
    [0, Math.max(typeFrames, 0.001)],
    [0, characters.length],
    clamp,
  );
  const visibleLength = Math.min(
    characters.length,
    Math.max(frame >= 0 ? 1 : 0, Math.floor(typedLength) + 1),
  );
  return characters.slice(0, visibleLength).join("");
}

export function TypedSplitWipe({
  prefix,
  anchor,
  suffix,
  typeFrames = 30,
  exitAt = 50,
  exitFrames = 20,
  wordStagger = 4,
  anchorShift = -72,
  fontSize = 42,
  color = "#e8e8e8",
  fontWeight = 400,
  speed = 1,
  className,
}: TypedSplitWipeProps) {
  const frame = useCurrentFrame() * speed;
  const fullText = [prefix, anchor, suffix].filter(Boolean).join(" ");
  const safeExitFrames = Math.max(exitFrames, 0.001);
  const typedText = getTypedSplitWipeText(fullText, frame, typeFrames);
  const suffixWords = suffix.trim().split(/\s+/).filter(Boolean);

  const textStyle: CSSProperties = {
    color,
    fontFamily:
      "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
    fontSize,
    fontWeight,
    letterSpacing: "-0.03em",
    lineHeight: 1,
    whiteSpace: "pre",
  };

  const prefixExit = interpolate(
    frame,
    [exitAt, exitAt + safeExitFrames],
    [0, 1],
    { ...clamp, easing: wipeEasing },
  );
  const anchorExitStart = exitAt + Math.max(exitFrames - 6, 0);
  const anchorExit = interpolate(
    frame,
    [anchorExitStart, anchorExitStart + 6],
    [0, 1],
    { ...clamp, easing: wipeEasing },
  );

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
        background: "transparent",
      }}
    >
      {frame < exitAt ? (
        <span className={className} style={textStyle}>
          {typedText}
        </span>
      ) : (
        <span
          className={className}
          style={{
            ...textStyle,
            display: "inline-flex",
            alignItems: "baseline",
            gap: "0.25em",
          }}
        >
          {prefix && (
            <span
              style={{
                display: "inline-block",
                clipPath: `inset(0 ${prefixExit * 100}% 0 0)`,
              }}
            >
              {prefix}
            </span>
          )}

          {anchor && (
            <span
              style={{
                display: "inline-block",
                clipPath: `inset(0 ${anchorExit * 50}% 0 ${anchorExit * 50}%)`,
                transform: `translateX(${anchorShift * prefixExit}px)`,
              }}
            >
              {anchor}
            </span>
          )}

          {suffixWords.map((word, index) => {
            const wordExitStart = exitAt + 2 + index * wordStagger;
            const wordExit = interpolate(
              frame,
              [wordExitStart, wordExitStart + safeExitFrames * 0.65],
              [0, 1],
              { ...clamp, easing: wipeEasing },
            );

            return (
              <span
                key={`${word}-${index}`}
                style={{
                  display: "inline-block",
                  clipPath: `inset(0 0 0 ${wordExit * 100}%)`,
                }}
              >
                {word}
              </span>
            );
          })}
        </span>
      )}
    </div>
  );
}

"use client";

import { Easing, interpolate, useCurrentFrame } from "remotion";

export interface ShadowSweepTextProps {
  text: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  backgroundColor?: string;
  shadowColor?: string;
  shadowSoftness?: number;
  rise?: number;
  driftLeft?: number;
  speed?: number;
  className?: string;
}

export const shadowSweepTextLength = 37;

const ENTER_END = 23;
const EXIT_START = 26;
const EXIT_END = shadowSweepTextLength - 1;
const REST_X = -20;
const REST_Y = 9;
const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

export function ShadowSweepText({
  text,
  fontSize = 96,
  color = "#aaa6b5",
  fontWeight = 700,
  backgroundColor = "#030012",
  shadowColor = backgroundColor,
  shadowSoftness = 130,
  rise = 96,
  driftLeft = 16,
  speed = 1,
  className,
}: ShadowSweepTextProps) {
  const frame = useCurrentFrame() * speed;
  const safeSoftness = Math.max(shadowSoftness, 0);
  const travelProgress = interpolate(
    frame,
    [0, shadowSweepTextLength - 1],
    [0, 1],
    {
      ...clamp,
      easing: Easing.out(Easing.cubic),
    },
  );
  const enterProgress = interpolate(frame, [-3, ENTER_END], [0, 1], clamp);
  const exitProgress = interpolate(
    frame,
    [EXIT_START, EXIT_END],
    [0, 1],
    clamp,
  );
  const x = REST_X + driftLeft * (1 - travelProgress);
  const y = REST_Y + rise * (1 - travelProgress);
  const isEntering = frame < ENTER_END;
  const isExiting = frame >= EXIT_START;
  const sweepProgress = isEntering
    ? enterProgress
    : isExiting
      ? exitProgress
      : null;
  const edgeOffset =
    sweepProgress === null ? 0 : (sweepProgress * 2 - 1) * (safeSoftness / 2);
  const edgePosition =
    sweepProgress === null
      ? "50%"
      : `calc(${sweepProgress * 100}% + ${edgeOffset}px)`;
  const maskStart =
    sweepProgress === null
      ? "50%"
      : `calc(${sweepProgress * 100}% + ${edgeOffset - safeSoftness / 2}px)`;
  const maskEnd =
    sweepProgress === null
      ? "50%"
      : `calc(${sweepProgress * 100}% + ${edgeOffset + safeSoftness / 2}px)`;
  const textMask = isEntering
    ? `linear-gradient(90deg, #000 0, #000 ${maskStart}, transparent ${maskEnd}, transparent 100%)`
    : isExiting
      ? `linear-gradient(90deg, transparent 0, transparent ${maskStart}, #000 ${maskEnd}, #000 100%)`
      : undefined;
  const fieldOpacity =
    sweepProgress === null
      ? 0
      : interpolate(sweepProgress, [0, 0.08, 0.82, 1], [0, 1, 1, 0], clamp);
  const fieldWidth = Math.max(safeSoftness * 3, 1);
  const fieldHeight = Math.max(fontSize * 2.6, safeSoftness * 1.8, 1);

  if (text.length === 0) {
    return (
      <div
        className={className}
        style={{ position: "absolute", inset: 0, backgroundColor }}
      />
    );
  }

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
        backgroundColor,
      }}
    >
      <div
        style={{
          position: "relative",
          display: "inline-block",
          transform: `translate3d(${x}px, ${y}px, 0)`,
        }}
      >
        <span
          style={{
            color,
            display: "inline-block",
            fontFamily: "Arial, Helvetica, sans-serif",
            fontSize,
            fontWeight,
            letterSpacing: 0,
            lineHeight: 1,
            maskImage: textMask,
            maskRepeat: "no-repeat",
            opacity: 1,
            WebkitMaskImage: textMask,
            WebkitMaskRepeat: "no-repeat",
            whiteSpace: "nowrap",
          }}
        >
          {text}
        </span>

        <div
          style={{
            position: "absolute",
            top: "50%",
            left: edgePosition,
            width: fieldWidth,
            height: fieldHeight,
            background: `radial-gradient(ellipse at center, ${shadowColor} 0%, ${shadowColor} 14%, transparent 72%)`,
            filter: `blur(${safeSoftness * 0.08}px)`,
            opacity: fieldOpacity,
            pointerEvents: "none",
            transform: "translate3d(-50%, -50%, 0)",
          }}
        />
      </div>
    </div>
  );
}

"use client";

import { useMemo } from "react";
import { Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

export interface OutlineFillTrackTextProps {
  leadText?: string;
  valueText?: string;
  fontSize?: number;
  fontWeight?: number;
  color?: string;
  outlineColor?: string;
  outlineWidth?: number;
  backgroundColor?: string;
  glowColor?: string;
  enterOffset?: number;
  anchorOffsetX?: number;
  trackDistance?: number;
  wordGap?: number;
  endPadding?: number;
  fillDuration?: number;
  speed?: number;
  className?: string;
}

export const outlineFillTrackTextLength = 80;

const ENTER_END = 16;
const TRACK_START = 16;
const TRACK_END = 72;
const FILL_START = 34;
const FILL_PREFILL = 10;
const FONT_FAMILY = "Arial, Helvetica, sans-serif";
const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

function estimateTextWidth(
  text: string,
  fontSize: number,
  fontWeight: number,
): number {
  if (typeof document === "undefined") {
    return text.length * fontSize * 0.56;
  }

  const context = document.createElement("canvas").getContext("2d");
  if (!context) return text.length * fontSize * 0.56;
  context.font = `${fontWeight} ${fontSize}px Arial`;
  return context.measureText(text).width;
}

export function OutlineFillTrackText({
  leadText = "Keep",
  valueText = "1000000000%",
  fontSize = 368,
  fontWeight = 700,
  color = "#f4f3f6",
  outlineColor = "#e6e2ed",
  outlineWidth = 3,
  backgroundColor = "#030012",
  glowColor = "#64109a",
  enterOffset = 240,
  anchorOffsetX = -84,
  trackDistance = 0,
  wordGap = 220,
  endPadding = 96,
  fillDuration = 38,
  speed = 1,
  className,
}: OutlineFillTrackTextProps) {
  const frame = useCurrentFrame() * Math.max(speed, 0);
  const { width: compositionWidth } = useVideoConfig();
  const safeFontSize = Math.max(fontSize, 1);
  const safeFontWeight = Math.max(fontWeight, 1);
  const safeOutlineWidth = Math.max(outlineWidth, 0);
  const safeGap = Math.max(wordGap, 0);
  const safeEndPadding = Math.max(endPadding, 0);
  const safeFillDuration = Math.max(fillDuration, 1);

  const measurements = useMemo(() => {
    const leadWidth = estimateTextWidth(leadText, safeFontSize, safeFontWeight);
    const valueWidth = estimateTextWidth(
      valueText,
      safeFontSize,
      safeFontWeight,
    );
    return {
      valueWidth,
      distance: leadWidth / 2 + safeGap + valueWidth / 2,
    };
  }, [leadText, safeFontSize, safeFontWeight, safeGap, valueText]);

  const valueOffset = trackDistance > 0 ? trackDistance : measurements.distance;
  const anchorX = compositionWidth / 2 + anchorOffsetX;
  const trailingOverflow = Math.max(
    0,
    anchorX + measurements.valueWidth / 2 - (compositionWidth - safeEndPadding),
  );
  const travelDistance = valueOffset + trailingOverflow;
  const enterProgress = interpolate(frame, [0, ENTER_END], [0, 1], {
    ...clamp,
    easing: Easing.bezier(0.16, 0.84, 0.24, 1),
  });
  const trackProgress = interpolate(frame, [TRACK_START, TRACK_END], [0, 1], {
    ...clamp,
    easing: Easing.bezier(0.42, 0, 0.58, 1),
  });
  const fillProgress = interpolate(
    frame,
    [FILL_START - FILL_PREFILL, FILL_START + safeFillDuration],
    [0, 1],
    clamp,
  );
  const leadY = enterOffset * (1 - enterProgress);
  const revealEdge = enterProgress * 112 - 8;
  const revealSolid = Math.max(0, Math.min(100, revealEdge - 10));
  const revealFade = Math.max(0, Math.min(100, revealEdge + 10));
  const leadMask = `linear-gradient(180deg, #000 0%, #000 ${revealSolid}%, transparent ${revealFade}%, transparent 100%)`;
  const glowOpacity = interpolate(
    enterProgress,
    [0, 0.18, 0.72, 1],
    [0.92, 1, 0.52, 0],
    clamp,
  );
  const fieldY = interpolate(enterProgress, [0, 1], [-42, -210], clamp);
  const textStyle = {
    display: "block",
    fontFamily: FONT_FAMILY,
    fontSize: safeFontSize,
    fontWeight: safeFontWeight,
    letterSpacing: 0,
    lineHeight: 0.86,
    whiteSpace: "nowrap" as const,
  };

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        backgroundColor,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `radial-gradient(ellipse 118% 66% at 50% -12%, ${glowColor} 0%, ${glowColor} 14%, transparent 76%)`,
          filter: `blur(${safeFontSize * 0.15}px)`,
          opacity: glowOpacity,
          pointerEvents: "none",
          transform: "translateZ(0)",
        }}
      />

      <div
        style={{
          position: "absolute",
          top: "50%",
          left: `calc(50% + ${anchorOffsetX}px)`,
          transform: `translate3d(${-travelDistance * trackProgress}px, -50%, 0)`,
        }}
      >
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            color,
            maskImage: leadMask,
            maskRepeat: "no-repeat",
            opacity: 1,
            transform: `translate3d(-50%, calc(-50% + ${leadY}px), 0)`,
            WebkitMaskImage: leadMask,
            WebkitMaskRepeat: "no-repeat",
            ...textStyle,
          }}
        >
          {leadText}
        </div>

        <div
          style={{
            position: "absolute",
            top: 0,
            left: valueOffset,
            transform: "translate3d(-50%, -50%, 0)",
            visibility: frame < FILL_START ? "hidden" : "visible",
          }}
        >
          <span
            style={{
              ...textStyle,
              color: "transparent",
              paintOrder: "stroke fill",
              WebkitTextStroke: `${safeOutlineWidth}px ${outlineColor}`,
            }}
          >
            {valueText}
          </span>
          <span
            style={{
              ...textStyle,
              position: "absolute",
              inset: 0,
              clipPath: `inset(0 ${100 - fillProgress * 100}% 0 0)`,
              color,
              opacity: 1,
            }}
          >
            {valueText}
          </span>
        </div>

        <div
          style={{
            position: "absolute",
            top: fieldY,
            left: 0,
            width: safeFontSize * 2.8,
            height: safeFontSize * 0.72,
            background: `radial-gradient(ellipse at center, ${backgroundColor} 0%, ${backgroundColor} 18%, transparent 74%)`,
            filter: `blur(${safeFontSize * 0.07}px)`,
            opacity: glowOpacity,
            pointerEvents: "none",
            transform: "translate3d(-50%, -50%, 0)",
          }}
        />
      </div>
    </div>
  );
}

