import { loadFont } from "@remotion/google-fonts/Caveat";
import { useCurrentFrame } from "remotion";
import { DEFAULT_STEP, hashRange, qf, qstep } from "@/lib/remocn/stop-motion";

const { fontFamily: HAND_FAMILY } = loadFont("normal", {
  subsets: ["latin"],
  weights: ["400", "500", "600", "700"],
});

export interface HandwriteProps {
  text: string;
  fontSize?: number;
  color?: string;
  delay?: number;
  perStep?: number;
  weight?: 400 | 500 | 600 | 700;
  align?: "left" | "center";
  fontFamily?: string;
  step?: number;
}

export function Handwrite({
  text,
  fontSize = 54,
  color = "#26242c",
  delay = 0,
  perStep = 1.6,
  weight = 600,
  align = "center",
  fontFamily = HAND_FAMILY,
  step = DEFAULT_STEP,
}: HandwriteProps) {
  const frame = useCurrentFrame();
  const steps = Math.max(0, qstep(Math.max(0, qf(frame, step) - delay), step));
  const shown = Math.floor(steps * perStep);
  const chars = Array.from(text);
  const freshFrom = shown - Math.ceil(perStep);

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: align === "center" ? "center" : "flex-start",
        background: "transparent",
      }}
    >
      <span
        style={{
          display: "inline-block",
          fontFamily: `${fontFamily}, cursive`,
          fontWeight: weight,
          fontSize,
          lineHeight: 1.15,
          color,
          whiteSpace: "pre-wrap",
          textAlign: align,
        }}
      >
        {chars.map((char, i) => {
          const visible = i < shown;
          const slant = hashRange(`hw:${text}:${i}:r`, -3.2, 3.2);
          const dy = hashRange(`hw:${text}:${i}:y`, -1.8, 1.8);
          const fresh = visible && i >= freshFrom;
          return (
            <span
              key={i}
              style={{
                display: "inline-block",
                whiteSpace: "pre",
                opacity: visible ? 1 : 0,
                translate: visible ? `0 ${dy}px` : undefined,
                rotate: visible ? `${slant}deg` : undefined,
                scale: visible ? `${fresh ? 1.06 : 1}` : undefined,
              }}
            >
              {char}
            </span>
          );
        })}
      </span>
    </div>
  );
}

export function handwriteDuration(
  text: string,
  options?: { perStep?: number; step?: number },
): number {
  const perStep = options?.perStep ?? 1.6;
  const step = options?.step ?? DEFAULT_STEP;
  return Math.ceil(Array.from(text).length / perStep) * step + step;
}

"use client";

import { loadFont } from "@remotion/google-fonts/Caveat";
import { useCurrentFrame } from "remotion";
import {
  DEFAULT_STEP,
  hashRange,
  qstep,
  steppedRamp,
} from "@/lib/remocn/stop-motion";

const { fontFamily: HAND_FAMILY } = loadFont("normal", {
  subsets: ["latin"],
  weights: ["400", "500", "600", "700"],
});

const easeOutCubic = (t: number) => 1 - (1 - t) ** 3;

const easeInOutCubic = (t: number) =>
  t < 0.5 ? 4 * t ** 3 : 1 - (-2 * t + 2) ** 3 / 2;

const DEFAULT_DURATION_STEPS = 18;

export type HandCountEase = "in-out" | "out" | "linear";

const EASES: Record<HandCountEase, (t: number) => number> = {
  "in-out": easeInOutCubic,
  out: easeOutCubic,
  linear: (t: number) => t,
};

export type HandCountTiming = {
  delay?: number;
  durationSteps?: number;
  step?: number;
};

export function handCountDuration(options?: HandCountTiming): number {
  const delay = options?.delay ?? 0;
  const durationSteps = options?.durationSteps ?? DEFAULT_DURATION_STEPS;
  const step = options?.step ?? DEFAULT_STEP;
  const end = delay + durationSteps * step;
  return Math.ceil(end / step) * step;
}

export function handCountValue(
  args: HandCountTiming & {
    frame: number;
    to: number;
    from?: number;
    ease?: HandCountEase;
  },
): number {
  const from = args.from ?? 0;
  const delay = args.delay ?? 0;
  const durationSteps = args.durationSteps ?? DEFAULT_DURATION_STEPS;
  const step = args.step ?? DEFAULT_STEP;
  const progress = steppedRamp(
    args.frame,
    delay,
    delay + durationSteps * step,
    {
      ease: EASES[args.ease ?? "in-out"],
      step,
    },
  );
  return from + (args.to - from) * progress;
}

export function handCountText(
  value: number,
  options?: { decimals?: number; prefix?: string; suffix?: string },
): string {
  return `${options?.prefix ?? ""}${value.toFixed(options?.decimals ?? 0)}${options?.suffix ?? ""}`;
}

export function handCountPose(
  frame: number,
  options?: HandCountTiming,
): number {
  const step = options?.step ?? DEFAULT_STEP;
  const settled = handCountDuration(options);
  return Math.min(qstep(Math.max(0, frame), step), qstep(settled, step));
}

export function handCountJitter(
  args: HandCountTiming & { frame: number; index: number; seed?: string },
): { rot: number; dy: number } {
  const seed = args.seed ?? "count";
  const pose = handCountPose(args.frame, args);
  return {
    rot: hashRange(`${seed}:${pose}:${args.index}:r`, -3.2, 3.2),
    dy: hashRange(`${seed}:${pose}:${args.index}:y`, -1.8, 1.8),
  };
}

export interface HandCountProps {
  to: number;
  from?: number;
  delay?: number;
  durationSteps?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  fontSize?: number;
  color?: string;
  weight?: 400 | 500 | 600 | 700;
  ease?: HandCountEase;
  align?: "left" | "center";
  fontFamily?: string;
  seed?: string;
  step?: number;
}

export function HandCount({
  to,
  from = 0,
  delay = 0,
  durationSteps = DEFAULT_DURATION_STEPS,
  decimals = 0,
  prefix = "",
  suffix = "",
  fontSize = 96,
  color = "#26242c",
  weight = 700,
  ease = "in-out",
  align = "center",
  fontFamily = HAND_FAMILY,
  seed = "count",
  step = DEFAULT_STEP,
}: HandCountProps) {
  const frame = useCurrentFrame();
  const value = handCountValue({
    frame,
    to,
    from,
    delay,
    durationSteps,
    step,
    ease,
  });
  const chars = Array.from(handCountText(value, { decimals, prefix, suffix }));

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: align === "center" ? "center" : "flex-start",
        background: "transparent",
      }}
    >
      <span
        style={{
          display: "inline-block",
          fontFamily: `${fontFamily}, cursive`,
          fontWeight: weight,
          fontSize,
          lineHeight: 1.15,
          color,
          whiteSpace: "pre",
          textAlign: align,
        }}
      >
        {chars.map((char, i) => {
          const { rot, dy } = handCountJitter({
            frame,
            index: i,
            seed,
            delay,
            durationSteps,
            step,
          });
          return (
            <span
              key={`${i}:${char}`}
              style={{
                display: "inline-block",
                whiteSpace: "pre",
                translate: `0 ${dy}px`,
                rotate: `${rot}deg`,
              }}
            >
              {char}
            </span>
          );
        })}
      </span>
    </div>
  );
}

