import { Spinner } from "@/components/remocn/spinner";
import { mixOklch, type RemocnTheme, useRemocnTheme } from "@/lib/remocn-ui";

export type ButtonState = "idle" | "hover" | "press" | "loading" | "success";

type ButtonVariant =
  | "default"
  | "secondary"
  | "destructive"
  | "outline"
  | "ghost";

type ButtonSize = "sm" | "default" | "lg";

export interface ButtonProps {
  state?: ButtonState;
  style?: ButtonStyle;
  label?: string;
  variant?: ButtonVariant;
  size?: ButtonSize;
  theme?: Partial<RemocnTheme>;
  primary?: string;
  speed?: number;
  align?: "start" | "center" | "end";
  className?: string;
}

function justify(align: "start" | "center" | "end"): string {
  return align === "start"
    ? "flex-start"
    : align === "end"
      ? "flex-end"
      : "center";
}

const CHECK_PATH_LENGTH = 14;

const SIZE_STYLES: Record<
  ButtonSize,
  { height: number; padding: string; fontSize: number; gap: number }
> = {
  sm: { height: 32, padding: "0 12px", fontSize: 13, gap: 6 },
  default: { height: 40, padding: "0 20px", fontSize: 15, gap: 8 },
  lg: { height: 48, padding: "0 28px", fontSize: 17, gap: 10 },
};

interface VariantTokens {
  bg: string;
  fg: string;
  hoverBg: string;
  border: string;
}

function variantTokens(
  variant: ButtonVariant,
  theme: RemocnTheme,
): VariantTokens {
  const variants = {
    secondary: {
      bg: theme.secondary,
      fg: theme.secondaryForeground,
      hoverBg: mixOklch(theme.secondary, theme.muted, 1),
      border: "transparent",
    },
    destructive: {
      bg: theme.destructive,
      fg: theme.destructiveForeground,
      hoverBg: mixOklch(theme.destructive, theme.foreground, 0.12),
      border: "transparent",
    },
    outline: {
      bg: "transparent",
      fg: theme.foreground,
      hoverBg: theme.accent,
      border: theme.border,
    },
    ghost: {
      bg: "transparent",
      fg: theme.foreground,
      hoverBg: theme.accent,
      border: "transparent",
    },
    default: {
      bg: theme.primary,
      fg: theme.primaryForeground,
      hoverBg: mixOklch(theme.primary, theme.foreground, 0.1),
      border: "transparent",
    },
  };

  return variants[variant] ?? variants.default;
}

export interface ButtonStyle {
  translateY: number;
  scale: number;
  background: string;
  labelOpacity: number;
  spinnerOpacity: number;
  checkOpacity: number;
}

export interface ButtonStyleContext {
  restBg: string;
  hoverBg: string;
  pressBg: string;
  primary: string;
}

export function buttonStyleContext(
  variant: ButtonVariant,
  theme: RemocnTheme,
): ButtonStyleContext {
  const tokens = variantTokens(variant, theme);
  const restBg = tokens.bg === "transparent" ? theme.background : tokens.bg;
  return {
    restBg,
    hoverBg: tokens.hoverBg,
    pressBg:
      tokens.bg === "transparent"
        ? tokens.hoverBg
        : mixOklch(tokens.hoverBg, theme.foreground, 0.08),
    primary: theme.primary,
  };
}

export function buttonStyle(
  state: ButtonState,
  ctx: ButtonStyleContext,
): ButtonStyle {
  switch (state) {
    case "hover":
      return {
        translateY: -1,
        scale: 1,
        background: ctx.hoverBg,
        labelOpacity: 1,
        spinnerOpacity: 0,
        checkOpacity: 0,
      };
    case "press":
      return {
        translateY: -1,
        scale: 0.97,
        background: ctx.pressBg,
        labelOpacity: 1,
        spinnerOpacity: 0,
        checkOpacity: 0,
      };
    case "loading":
      return {
        translateY: -1,
        scale: 1,
        background: ctx.hoverBg,
        labelOpacity: 0,
        spinnerOpacity: 1,
        checkOpacity: 0,
      };
    case "success":
      return {
        translateY: -1,
        scale: 1,
        background: ctx.primary,
        labelOpacity: 0,
        spinnerOpacity: 0,
