            width: WIDTH,
            height: 40,
            padding: "0 16px",
            fontSize: 15,
            fontWeight: 500,
            letterSpacing: "-0.01em",
            color: ctx.triggerFg,
            background: trigger.background,
            border: `1px solid ${ctx.panelBorder}`,
