"use client";

import {
  clamp01,
  mixOklch,
  type RemocnTheme,
  useRemocnTheme,
} from "@/lib/remocn-ui";

export interface StepperStyle {
  position: number;
}

export type StepperOrientation = "horizontal" | "vertical";

export interface StepperProps {
  steps?: string[];
  activeIndex?: number;
  style?: StepperStyle;
  orientation?: StepperOrientation;
  theme?: Partial<RemocnTheme>;
  className?: string;
}

const DEFAULT_STEPS = ["Account", "Plan", "Done"];

const CIRCLE = 36;
const CHECK_PATH_LENGTH = 14;

export interface StepperStyleContext {
  primary: string;
  primaryFg: string;
  mutedBg: string;
  border: string;
  mutedFg: string;
  foreground: string;
}

export function stepperStyleContext(theme: RemocnTheme): StepperStyleContext {
  return {
    primary: theme.primary,
    primaryFg: theme.primaryForeground,
    mutedBg: theme.muted,
    border: theme.border,
    mutedFg: theme.mutedForeground,
    foreground: theme.foreground,
  };
}

export function stepperStyle(activeIndex: number): StepperStyle {
  return { position: activeIndex };
}

export function stepCircleAt(
  i: number,
  position: number,
): {
  fill: number;
  checkDraw: number;
  active: boolean;
} {
  const fill = clamp01(position - i);
  const checkDraw = fill;
  const active = Math.floor(position) === i && fill < 1;
  return { fill, checkDraw, active };
}

export function connectorFillAt(i: number, position: number): number {
  return clamp01(position - i);
}

export function Stepper({
  steps = DEFAULT_STEPS,
  activeIndex = 0,
  style,
  orientation: _orientation = "horizontal",
  theme: themeOverride,
  className,
}: StepperProps) {
  const theme = useRemocnTheme(themeOverride, "light");
  const ctx = stepperStyleContext(theme);
  const v = style ?? stepperStyle(activeIndex);
  const position = v.position;

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "transparent",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
      }}
    >
      <div style={{ display: "flex", alignItems: "flex-start" }}>
        {steps.map((label, i) => {
          const { fill, checkDraw, active } = stepCircleAt(i, position);
          const completed = fill >= 1;
          const circleBg = mixOklch(ctx.mutedBg, ctx.primary, fill);
          const circleBorder = mixOklch(ctx.border, ctx.primary, fill);
          const numberOpacity = 1 - checkDraw;
          const numberColor =
            active || completed ? ctx.foreground : ctx.mutedFg;
          const isLast = i === steps.length - 1;
          return (
            <div
              key={label}
              style={{ display: "flex", alignItems: "flex-start" }}
            >
              {}
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  gap: 8,
                  width: CIRCLE + 24,
                }}
              >
                <div
                  style={{
                    position: "relative",
                    width: CIRCLE,
                    height: CIRCLE,
                    borderRadius: "50%",
                    background: circleBg,
                    border: `2px solid ${active ? ctx.primary : circleBorder}`,
                    boxSizing: "border-box",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  {}
                  <span
                    style={{
                      position: "absolute",
                      fontSize: 14,
                      fontWeight: 600,
                      color: numberColor,
                      opacity: numberOpacity,
                    }}
                  >
                    {i + 1}
                  </span>
                  {}
                  <svg
                    width={CIRCLE}
                    height={CIRCLE}
                    viewBox="0 0 24 24"
                    fill="none"
                  >
                    <path
                      d="M5 12.5l4.5 4.5L19 7"
                      stroke={ctx.primaryFg}
                      strokeWidth="2.6"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      pathLength={CHECK_PATH_LENGTH}
                      strokeDasharray={CHECK_PATH_LENGTH}
                      strokeDashoffset={CHECK_PATH_LENGTH * (1 - checkDraw)}
                    />
                  </svg>
                </div>
                <span
                  style={{
                    fontSize: 13,
                    fontWeight: 500,
                    letterSpacing: "-0.01em",
                    color: active || completed ? ctx.foreground : ctx.mutedFg,
                    whiteSpace: "nowrap",
                  }}
                >
                  {label}
                </span>
              </div>
              {}
              {!isLast && (
                <div
                  style={{
                    position: "relative",
                    width: 64,
                    height: 2,
                    marginTop: CIRCLE / 2 - 1,
                    background: ctx.border,
                    overflow: "hidden",
                  }}
                >
                  <div
                    style={{
                      position: "absolute",
                      left: 0,
                      top: 0,
                      bottom: 0,
                      width: `${connectorFillAt(i, position) * 100}%`,
                      background: ctx.primary,
                    }}
                  />
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { useCurrentFrame } from "remotion";
import type { StepperStyle } from "@/components/remocn/stepper";
import { clamp01, type EasingName, easings } from "@/lib/remocn-ui";

export interface StepperStep {
  at: number;
  index: number;
  duration?: number;
  easing?: EasingName;
}

export const DEFAULT_DURATION = 24;

export interface StepperTransitionOptions {
  speed?: number;
  defaultDuration?: number;
}

export function tweenStepperStyle(
  a: StepperStyle,
  b: StepperStyle,
  t: number,
): StepperStyle {
  return { position: a.position + (b.position - a.position) * t };
}

export function useStepperTransition(
  steps: StepperStep[],
  opts: StepperTransitionOptions = {},
): StepperStyle {
  const { speed = 1 } = opts;
  const raw = useCurrentFrame() * speed;
  return stepperStyleAt(steps, raw, opts);
}

export function stepperStyleAt(
  steps: StepperStep[],
  raw: number,
  opts: StepperTransitionOptions = {},
): StepperStyle {
  const { defaultDuration = DEFAULT_DURATION } = opts;

  if (steps.length === 0) return { position: 0 };

  const first = steps[0];

  if (raw <= first.at) return { position: first.index };

  let toIndex = steps.length - 1;
  for (let i = 1; i < steps.length; i++) {
    if (steps[i].at > raw) {
      toIndex = i;
      break;
    }
  }
  const pastLast = raw >= steps[steps.length - 1].at;
  const to = pastLast ? steps[steps.length - 1] : steps[toIndex];
  const from = pastLast ? steps[steps.length - 1] : steps[toIndex - 1];

  const dur = to.duration ?? defaultDuration;
  const ease = easings[to.easing ?? "out"];
  const start = to.at - dur;
  const t = pastLast || dur <= 0 ? 1 : ease(clamp01((raw - start) / dur));
  const position = from.index + (to.index - from.index) * t;

  return { position };
}

"use client";

import { type RemocnTheme, useRemocnTheme } from "@/lib/remocn-ui";

export type SwitchState = "unchecked" | "checked";

type SwitchSize = "sm" | "default" | "lg";

export interface SwitchProps {
  state?: SwitchState;
  style?: SwitchStyle;
  label?: string;
  size?: SwitchSize;
  theme?: Partial<RemocnTheme>;
  primary?: string;
  className?: string;
}

const SIZE_STYLES: Record<
  SwitchSize,
  {
    trackW: number;
    trackH: number;
    thumb: number;
    pad: number;
    fontSize: number;
    gap: number;
  }
> = {
  sm: { trackW: 36, trackH: 20, thumb: 16, pad: 2, fontSize: 13, gap: 8 },
  default: { trackW: 44, trackH: 24, thumb: 20, pad: 2, fontSize: 15, gap: 10 },
  lg: { trackW: 52, trackH: 28, thumb: 24, pad: 2, fontSize: 17, gap: 12 },
};

export interface SwitchStyle {
  trackBackground: string;
  thumbOffset: number;
}

export interface SwitchStyleContext {
  uncheckedTrack: string;
  checkedTrack: string;
  thumbColor: string;
}

export function switchStyleContext(theme: RemocnTheme): SwitchStyleContext {
  return {
    uncheckedTrack: theme.input,
    checkedTrack: theme.primary,
    thumbColor: theme.background,
  };
}

export function switchStyle(
  state: SwitchState,
  ctx: SwitchStyleContext,
): SwitchStyle {
  switch (state) {
    case "checked":
      return {
        trackBackground: ctx.checkedTrack,
        thumbOffset: 1,
      };
    default:
      return {
        trackBackground: ctx.uncheckedTrack,
        thumbOffset: 0,
      };
  }
}

export function Switch({
  state = "unchecked",
  style,
  label,
  size = "default",
  theme: themeOverride,
  primary,
  className,
}: SwitchProps) {
  const theme = useRemocnTheme(
    { ...themeOverride, ...(primary ? { primary } : {}) },
    "light",
  );

  const sizeStyle = SIZE_STYLES[size];
  const ctx = switchStyleContext(theme);
  const v = style ?? switchStyle(state, ctx);

  const travel = sizeStyle.trackW - sizeStyle.thumb - sizeStyle.pad * 2;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "transparent",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
      }}
    >
      <span
        className={className}
        style={{
          display: "inline-flex",
          alignItems: "center",
          gap: sizeStyle.gap,
        }}
      >
        {}
        <span
          style={{
            position: "relative",
            display: "flex",
            alignItems: "center",
            width: sizeStyle.trackW,
            height: sizeStyle.trackH,
            borderRadius: sizeStyle.trackH / 2,
            background: v.trackBackground,
          }}
        >
          {}
          <span
            style={{
              position: "absolute",
              left: sizeStyle.pad,
              width: sizeStyle.thumb,
              height: sizeStyle.thumb,
              borderRadius: "50%",
              background: ctx.thumbColor,
              boxShadow: "0 1px 2px rgba(0,0,0,0.15)",
              transform: `translateX(${v.thumbOffset * travel}px)`,
            }}
          />
        </span>
        {label !== undefined && (
          <span
            style={{
              fontSize: sizeStyle.fontSize,
              fontWeight: 500,
              letterSpacing: "-0.01em",
              color: theme.foreground,
            }}
          >
            {label}
          </span>
        )}
      </span>
    </div>
  );
}

"use client";

import {
  type SwitchState,
  type SwitchStyle,
  switchStyle,
  switchStyleContext,
} from "@/components/remocn/switch";
import {
  easings,
  mixOklch,
  type RemocnTheme,
  type Step,
  useRemocnTheme,
  useStateTransition,
} from "@/lib/remocn-ui";

export const DEFAULT_DURATION = 10;

export function tweenSwitchStyle(
  a: SwitchStyle,
  b: SwitchStyle,
  t: number,
): SwitchStyle {
  return {
    trackBackground: mixOklch(a.trackBackground, b.trackBackground, t),
    thumbOffset: a.thumbOffset + (b.thumbOffset - a.thumbOffset) * t,
  };
}

export interface SwitchTransitionOptions {
  theme?: Partial<RemocnTheme>;
  mode?: "light" | "dark";
  primary?: string;
  speed?: number;
  defaultDuration?: number;
}

export function useSwitchTransition(
  steps: Step<SwitchState>[],
  opts: SwitchTransitionOptions = {},
): SwitchStyle {
  const {
    theme: themeOverride,
    mode,
    primary,
    speed = 1,
    defaultDuration = DEFAULT_DURATION,
  } = opts;
  const theme = useRemocnTheme(
    { ...themeOverride, ...(primary ? { primary } : {}) },
    mode,
  );
  const ctx = switchStyleContext(theme);
  const { from, to, progress } = useStateTransition(
    steps,
    "unchecked",
    speed,
    defaultDuration,
  );
  const t = easings.out(progress);
  return tweenSwitchStyle(switchStyle(from, ctx), switchStyle(to, ctx), t);
}

