export function ChatFlow({
  messages = DEFAULT_MESSAGES,
  contact,
  accentColor,
  speed = 1,
  theme: themeOverride,
}: ChatFlowProps) {
  const frame = useCurrentFrame();
  const eff = frame * speed;

  const themeProp = {
    ...themeOverride,
    ...(accentColor ? { primary: accentColor } : {}),
  };
  const resolved = useRemocnTheme(themeProp, "light");

  const { items } = chatFlowSchedule(messages);

  const activeMe = items.find(
    (item) =>
      item.from === "me" &&
      item.typeStart !== undefined &&
      item.sendAt !== undefined &&
      eff >= item.typeStart &&
      eff < item.sendAt,
  );
  let composerText = "";
  let typing = false;
  if (
    activeMe &&
    activeMe.typeStart !== undefined &&
    activeMe.sendAt !== undefined
  ) {
    const typeDur = Math.max(
      activeMe.sendAt - SEND_GAP - activeMe.typeStart,
      1,
    );
    const progress = clamp((eff - activeMe.typeStart) / typeDur, 0, 1);
    composerText = revealedText(
      activeMe.text,
      Math.floor(progress * activeMe.text.length),
    );
    typing = true;
  }

  const sendActive = composerText.length > 0;
  const sendScale = 1 - 0.16 * sendPulse(items, eff);
  const present = items.filter((item) => eff >= item.presenceStart);

  const composerBackground = mixOklch(
    resolved.background,
    resolved.muted,
    0.55,
  );

  return (
    <div
      style={{
        position: "relative",
        width: "100%",
        height: "100%",
        display: "flex",
        justifyContent: "center",
        background: "transparent",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          width: "100%",
          maxWidth: MOBILE_WIDTH,
          height: "100%",
          padding: "24px 16px 18px",
          boxSizing: "border-box",
        }}
      >
        {contact !== undefined && (
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 10,
              paddingBottom: 16,
              marginBottom: 8,
              borderBottom: `1px solid ${resolved.border}`,
            }}
          >
            <Avatar contact={contact} theme={resolved} />
            <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
              <span
                style={{
                  fontSize: 15,
                  fontWeight: 600,
                  lineHeight: 1.25,
                  letterSpacing: "-0.01em",
                  color: resolved.foreground,
                }}
              >
                {contact.name}
              </span>
              <span
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 5,
                  fontSize: 12,
                  lineHeight: 1.2,
                  color: "oklch(0.62 0.17 150)",
                }}
              >
                <span
                  style={{
                    width: 6,
                    height: 6,
                    borderRadius: "50%",
                    background: "oklch(0.62 0.17 150)",
                  }}
                />
                online
              </span>
            </div>
          </div>
        )}

        <div
          style={{
            position: "relative",
            flex: 1,
            minHeight: 0,
            overflow: "hidden",
            WebkitMaskImage:
              "linear-gradient(to bottom, transparent 0, #000 48px, #000 100%)",
            maskImage:
              "linear-gradient(to bottom, transparent 0, #000 48px, #000 100%)",
          }}
        >
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              justifyContent: "flex-end",
              gap: 20,
              minHeight: "100%",
              paddingTop: 24,
              paddingBottom: 22,
            }}
          >
            {present.map((item) => (
              <ChatRow
                key={item.index}
                item={item}
                eff={eff}
                speed={speed}
                contact={contact}
                themeProp={themeProp}
                theme={resolved}
              />
            ))}
          </div>
        </div>

        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 10,
            marginTop: 14,
            padding: 14,
            borderRadius: 24,
            background: composerBackground,
            border: `1px solid ${resolved.border}`,
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "flex-start",
              minHeight: 24,
              fontSize: 15,
              lineHeight: 1.45,
              letterSpacing: "-0.01em",
              color: sendActive
                ? resolved.foreground
                : resolved.mutedForeground,
            }}
          >
            <span style={{ whiteSpace: "pre-wrap", wordBreak: "break-word" }}>
              {sendActive ? composerText : "Message"}
            </span>
            {typing && (
              <Caret
                color={resolved.foreground}
                height={18}
                radius={1}
                blink
                marginLeft={composerText.length > 0 ? 2 : 0}
              />
            )}
          </div>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <div
              style={{
                width: 38,
                height: 38,
                borderRadius: "50%",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                border: `1px solid ${resolved.border}`,
                background: "transparent",
              }}
            >
              <PlusIcon color={resolved.mutedForeground} />
            </div>
            <div
              style={{
                width: 38,
                height: 38,
                borderRadius: "50%",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                background: sendActive
                  ? resolved.primary
                  : mixOklch(resolved.background, resolved.muted, 0.6),
                transform: `scale(${sendScale})`,
              }}
            >
              <SendIcon
                color={
                  sendActive
                    ? resolved.primaryForeground
                    : resolved.mutedForeground
                }
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function ChatRow({
  item,
  eff,
  speed,
  contact,
  themeProp,
  theme,
}: {
  item: ScheduledMessage;
  eff: number;
  speed: number;
  contact?: ChatContact;
  themeProp: Partial<RemocnTheme>;
  theme: RemocnTheme;
}) {
  const { fps } = useVideoConfig();
  const variant = item.from === "me" ? "outgoing" : "incoming";
  const showTyping =
    item.from === "them" &&
    item.typingStart !== undefined &&
    eff < item.revealAt;

  const bubbleStyle = useMessageBubbleTransition(
    [{ at: item.revealAt, state: "visible", duration: REVEAL }],
    { speed },
  );

  let reactionStyle: MessageBubbleReactionStyle | undefined;
  if (item.reactAt !== undefined) {
    const reactAt = item.reactAt;
    const pop = spring({
      fps,
      frame: eff - reactAt,
      config: { damping: 11, stiffness: 220, mass: 0.6 },
    });
    const opacity = interpolate(eff, [reactAt, reactAt + 5], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    reactionStyle = { opacity, scale: pop };
  }

  const bubbleNode = showTyping ? (
    <MessageBubble
      variant="incoming"
      style={typingBubbleStyle(eff, item.typingStart ?? 0, item.revealAt)}
      theme={themeProp}
    >
      <TypingIndicator color={theme.mutedForeground} />
    </MessageBubble>
  ) : (
    <MessageBubble
      variant={variant}
      style={bubbleStyle}
      reaction={item.reaction}
      reactionStyle={reactionStyle}
      theme={themeProp}
    >
      {item.text}
    </MessageBubble>
  );

  if (item.from === "them" && contact !== undefined) {
    return (
      <div style={{ display: "flex", alignItems: "flex-end", gap: 8 }}>
        <Avatar contact={contact} theme={theme} />
        <div style={{ flex: 1, minWidth: 0 }}>{bubbleNode}</div>
      </div>
    );
  }

  return bubbleNode;
}

