export interface SettingsToggleFlowProps {
  title?: string;
  description?: string;
  rows?: { label: string }[];
  selectItems?: string[];
  saveLabel?: string;
  toastTitle?: string;
  theme?: Partial<RemocnTheme>;
}

export function SettingsToggleFlow({
  title = "Notification settings",
  description = "Manage how you receive alerts, set your theme, and tune the volume.",
  rows = DEFAULT_ROWS,
  selectItems = DEFAULT_SELECT_ITEMS,
  saveLabel = "Save settings",
  toastTitle = "Settings saved",
  theme,
}: SettingsToggleFlowProps) {
  const resolved = useRemocnTheme(theme);
  const opts = { theme };

  const lastItem = selectItems.length - 1;
  const ITEM_CY =
    PANEL_TOP + PANEL_PAD + lastItem * (ITEM_H + ITEM_GAP) + ITEM_H / 2;

  const cardEnter = useBlurInTransition(
    [{ at: 0, state: "revealed", duration: 18 }],
    { distance: 0 },
  );
  const enterHeader = useBlurInTransition([
    { at: 18, state: "revealed", duration: 16 },
  ]);
  const enterSwitch = useBlurInTransition([
    { at: 24, state: "revealed", duration: 16 },
  ]);
  const enterTheme = useBlurInTransition([
    { at: 30, state: "revealed", duration: 16 },
  ]);
  const enterVolume = useBlurInTransition([
    { at: 36, state: "revealed", duration: 16 },
  ]);
  const enterSave = useBlurInTransition([
    { at: 42, state: "revealed", duration: 16 },
  ]);

  const reveal = (e: {
    opacity: number;
    blur: number;
    translateX: number;
    translateY: number;
  }) => ({
    opacity: e.opacity,
    filter: e.blur > 0 ? `blur(${e.blur}px)` : "none",
    transform: `translate(${e.translateX}px, ${e.translateY}px)`,
  });

  const cursorStyle = useCursorPath([
    { at: 0, x: 220, y: 130 },
    { at: 24 + DEMO, x: SWITCH_CX, y: SWITCH_CY, duration: 20 },
    { at: 24 + DEMO, x: SWITCH_CX, y: SWITCH_CY, click: true, duration: 0 },
    { at: 55 + DEMO, x: TRIGGER_CX, y: TRIGGER_CY, duration: 22 },
    { at: 55 + DEMO, x: TRIGGER_CX, y: TRIGGER_CY, click: true, duration: 0 },
    { at: 80 + DEMO, x: ITEM_CX, y: ITEM_CY, duration: 18 },
    { at: 80 + DEMO, x: ITEM_CX, y: ITEM_CY, click: true, duration: 0 },
    { at: 105 + DEMO, x: THUMB_X_AT_20, y: SLIDER_CY, duration: 18 },
    {
      at: 105 + DEMO,
      x: THUMB_X_AT_20,
      y: SLIDER_CY,
      press: true,
      duration: 0,
    },
    {
      at: 150 + DEMO,
      x: THUMB_X_AT_80,
      y: SLIDER_CY,
      press: true,
      duration: 45,
    },
    { at: 158 + DEMO, x: THUMB_X_AT_80, y: SLIDER_CY, duration: 0 },
    { at: 180 + DEMO, x: SAVE_CX, y: SAVE_CY, duration: 18 },
    { at: 180 + DEMO, x: SAVE_CX, y: SAVE_CY, click: true, duration: 0 },
  ]);

  const switchStyle = useSwitchTransition(
    [{ at: 24 + DEMO, state: "checked", duration: 12 }],
    opts,
  );

  const panelStyle = useSelectTransition(
    [
      { at: 55 + DEMO, state: "opened", duration: 14 },
      { at: 90 + DEMO, state: "closed", duration: 12 },
    ],
    opts,
  );

  const triggerStyle = useButtonTransition(
    [
      { at: 45 + DEMO, state: "hover", duration: 8 },
      { at: 55 + DEMO, state: "press", duration: 8 },
    ],
    { variant: "outline", ...opts },
  );

  const itemStyle = useSelectItemTransition(
    [
      { at: 68 + DEMO, state: "hover", duration: 8 },
      { at: 78 + DEMO, state: "press", duration: 6 },
      { at: 80 + DEMO, state: "selected", duration: 10 },
    ],
    opts,
  );

  const sliderStyle = useSliderTransition([
    { at: 0, value: 20, thumbState: "idle" },
    { at: 105 + DEMO, thumbState: "press", duration: 6 },
    { at: 105 + DEMO, value: 20 },
    { at: 150 + DEMO, value: 80, duration: 45, easing: "inOut" },
    { at: 158 + DEMO, thumbState: "idle", duration: 8 },
  ]);

  const saveStyle = useButtonTransition(
    [
      { at: 172 + DEMO, state: "hover", duration: 8 },
      { at: 180 + DEMO, state: "press", duration: 6 },
      { at: 188 + DEMO, state: "success", duration: 14 },
    ],
    opts,
  );

  const toastStyle = useToastTransition(
    [
      { at: 196 + DEMO, state: "visible", duration: 12 },
      { at: 256 + DEMO, state: "hidden", duration: 12 },
    ],
    {},
  );

  const rowLabelStyle = {
    fontSize: 14,
    fontWeight: 500,
    letterSpacing: "-0.01em",
    color: resolved.foreground,
  } as const;

  return (
    <div
      style={{
        position: "relative",
        width: "100%",
        height: "100%",
        background: "transparent",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
      }}
    >
      {}
      <div
        style={{
          position: "absolute",
          left: CARD_LEFT,
          top: CARD_TOP,
          width: CARD_W,
          height: CARD_H,
          boxSizing: "border-box",
          background: resolved.background,
          border: `1px solid ${resolved.border}`,
          borderRadius: 16,
          boxShadow:
            "0 10px 30px -12px rgba(0,0,0,0.22), 0 2px 8px -3px rgba(0,0,0,0.10)",
          opacity: cardEnter.opacity,
          filter: cardEnter.blur > 0 ? `blur(${cardEnter.blur}px)` : "none",
        }}
      />

      {}
      <div
        style={{
          position: "absolute",
          left: LEFT_X,
          top: NOTIF_LABEL_Y,
          width: COL_W,
          display: "flex",
          flexDirection: "column",
          gap: 10,
          ...reveal(enterHeader),
        }}
      >
        <div
          style={{
            fontSize: 22,
            lineHeight: "28px",
            fontWeight: 600,
            letterSpacing: "-0.02em",
            color: resolved.foreground,
          }}
        >
          {title}
        </div>
        <div
          style={{
            fontSize: 14,
            lineHeight: "22px",
            color: resolved.mutedForeground,
          }}
        >
          {description}
        </div>
      </div>

      {}
      <div
        style={{
          position: "absolute",
          left: RIGHT_X,
          top: NOTIF_LABEL_Y,
          ...rowLabelStyle,
          ...reveal(enterSwitch),
        }}
      >
        {rows[0]?.label ?? "Notifications"}
      </div>
      <div
        style={{
          position: "absolute",
          left: RIGHT_X,
          top: SWITCH_TOP,
          width: SWITCH_W,
          height: SWITCH_H,
          ...reveal(enterSwitch),
        }}
      >
        <Switch style={switchStyle} theme={theme} />
      </div>

      {}
      <div
        style={{
          position: "absolute",
          left: RIGHT_X,
          top: VOL_LABEL_Y,
          ...rowLabelStyle,
          ...reveal(enterVolume),
        }}
      >
        {rows[2]?.label ?? "Volume"}
      </div>
      <div
        style={{
          position: "absolute",
          left: SLIDER_X0,
          top: SLIDER_TOP,
          ...reveal(enterVolume),
        }}
      >
        <Slider style={sliderStyle} width={SLIDER_W} theme={theme} />
      </div>

      {}
      <div
        style={{
          position: "absolute",
          left: RIGHT_X,
          top: THEME_LABEL_Y,
          ...rowLabelStyle,
          ...reveal(enterTheme),
        }}
      >
        {rows[1]?.label ?? "Theme"}
      </div>
      <div
        style={{
          position: "absolute",
          left: RIGHT_X,
          top: TRIGGER_TOP,
          width: SELECT_W,
          height: TRIGGER_H,
          ...reveal(enterTheme),
        }}
      >
        <Select
          style={panelStyle}
          label={selectItems[0] ?? "System"}
          items={selectItems}
          triggerStyle={triggerStyle}
          itemStyles={selectItems.map((_, i) =>
            i === selectItems.length - 1 ? itemStyle : undefined,
          )}
          theme={theme}
        />
      </div>

      {}
      <div
        style={{
          position: "absolute",
          left: SAVE_LEFT,
          top: SAVE_TOP,
          width: SAVE_W,
          height: SAVE_H,
          ...reveal(enterSave),
        }}
      >
        <Button label={saveLabel} style={saveStyle} theme={theme} />
      </div>

      {}
      <div style={{ position: "absolute", right: 24, bottom: 24 }}>
        <Toast
          style={toastStyle}
          title={toastTitle}
          variant="success"
          theme={theme}
        />
      </div>

      <Cursor style={cursorStyle} variant="pointer" theme={theme} />
    </div>
  );
}

"use client";

import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export type SearchRevealProps = {
  text?: string;
  fieldWidth?: number;
  fontSize?: number;
  framesPerCharacter?: number;
  showPanel?: boolean;
  showGuides?: boolean;
  color?: string;
  fieldColor?: string;
  ringColor?: string;
  panelColor?: string;
  accentColor?: string;
  backgroundColor?: string;
  speed?: number;
  reducedMotion?: boolean;
  className?: string;
};

export const searchRevealLength = 90;
const finite = (value: number | undefined, fallback: number) =>
  typeof value === "number" && Number.isFinite(value) ? value : fallback;
const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));
const letters = (text: string) =>
  Array.from(
    new Intl.Segmenter("en", { granularity: "grapheme" }).segment(text),
    (part) => part.segment,
  );
const curve = Easing.bezier(0.22, 1, 0.36, 1);
const tween = (frame: number, start: number, end: number, from = 0, to = 1) =>
  interpolate(frame, [start, end], [from, to], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: curve,
  });

function timing(props: SearchRevealProps) {
  const characters = letters(props.text ?? "remocn");
  const step = clamp(finite(props.framesPerCharacter, 4), 1, 12);
  const end = Math.max(searchRevealLength, 54 + characters.length * step + 10);
  return { characters, step, end, speed: Math.max(0, finite(props.speed, 1)) };
}

/** Demo duration at 30 fps, including an 18-frame final hold. */
export function getSearchRevealDuration(props: SearchRevealProps = {}) {
  const { end, speed } = timing(props);
  return speed === 0 ? 1 : Math.ceil((end + 18) / speed);
}

/** Frame is expressed at 30 fps; playback speed is applied here. */
export function getSearchRevealState(
  frame: number,
  props: SearchRevealProps = {},
) {
  const { characters, step, end, speed } = timing(props);
  const t = props.reducedMotion ? end : Math.max(0, finite(frame, 0)) * speed;
  const typedCount = clamp(Math.floor((t - 54) / step), 0, characters.length);
  const width = clamp(finite(props.fieldWidth, 464), 320, 640);
  const reveal = props.showPanel === false ? 0 : tween(t, 56, 90);
  const fieldWidth = tween(t, 26, 48, 130, width);
  const fieldHeight = tween(t, 26, 46, 24, 80);
  const panelWidth =
    fieldWidth + (Math.max(774, width + 170) - fieldWidth) * reveal;
  const panelHeight = fieldHeight + (374 - fieldHeight) * reveal;
  return {
    t,
    end,
    typedCount,
    text: characters.slice(0, typedCount).join(""),
    circleRadius: tween(t, 0, 26, 250, 410),
    circleOffset: tween(t, 0, 26, 62, 185),
    circlesVisible: t < 26,
    fieldVisible: t >= 26,
    fieldWidth,
    fieldHeight,
    tilt: tween(t, 26, 47, -4, 0),
    iconOpacity: tween(t, 34, 46),
    panelWidth,
    panelHeight,
    panelRadius: 40 * (1 - reveal),
    panelOpacity: tween(t, 56, 60),
    reveal,
    caretVisible:
      t >= 52 &&
      t < end &&
      (typedCount < characters.length || Math.floor((t - 52) / 12) % 2 === 0),
  };
}

function Cross({ x, y, size = 9 }: { x: number; y: number; size?: number }) {
  return (
    <path
      d={`M ${x - size} ${y} H ${x + size} M ${x} ${y - size} V ${y + size}`}
    />
  );
}

/** A video scene: expanding construction circles, a search pill, and typed copy. */
export function SearchReveal({
  text = "remocn",
  fieldWidth = 464,
  fontSize = 34,
  framesPerCharacter = 4,
  showPanel = true,
  showGuides = true,
  color = "#26232b",
  fieldColor = "#ffffff",
  ringColor = "#cbc5cf",
