              flexDirection: "column",
              gap: 4,
              fontSize,
              lineHeight: 1.55,
            }}
          >
            {lines.map((line, i) => (
              <Sequence
                key={i}
                from={Math.round((i * staggerFrames) / speed)}
                layout="none"
