function Light({ color }: { color: string }) {
  return (
    <div
      style={{
        width: 12,
        height: 12,
        borderRadius: "50%",
        background: color,
        opacity: 0.6,
      }}
    />
  );
}

function CodeLine({
  line,
  index,
  fontSize,
}: {
  line: string;
  index: number;
  fontSize: number;
}) {
  const frame = useCurrentFrame();
  const opacity = interpolate(frame, [0, 8], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const ty = interpolate(frame, [0, 8], [4, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const tokens = tokenizeLine(line);
  // Render an empty line as a half-height spacer so blank lines still take
  // visual space without collapsing the gap.
  if (tokens.length === 0) {
    return <div style={{ height: fontSize * 0.8, opacity }} />;
  }
  return (
    <div
      style={{
        opacity,
        translate: `0 ${ty}px`,
        whiteSpace: "pre",
        display: "flex",
        gap: 0,
      }}
    >
      <span style={{ width: 28, color: "#3f3f46", userSelect: "none" }}>
        {String(index + 1).padStart(2, " ")}
      </span>
      <span>
        {tokens.map((t, i) => (
          <span key={i} style={{ color: TOKEN_COLORS[t.kind] }}>
            {t.text}
          </span>
        ))}
      </span>
    </div>
  );
}

function BackdropAura() {
  // Slow, low-amplitude blob behind the glass so the backdrop blur has
  // perceptible content to refract.
  const frame = useCurrentFrame();
  const t = frame / 60;
  const x = 50 + Math.sin(t) * 20;
  const y = 50 + Math.cos(t * 0.7) * 15;
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        pointerEvents: "none",
        background: `radial-gradient(circle at ${x}% ${y}%, rgba(56,189,248,0.22), transparent 50%), radial-gradient(circle at ${100 - x}% ${100 - y}%, rgba(168,85,247,0.18), transparent 55%)`,
      }}
    />
  );
}

"use client";

import { AbsoluteFill, Easing, interpolate, useCurrentFrame } from "remotion";

import { GlassCodeBlock } from "@/components/remocn/glass-code-block";

export interface GlassCodeWalkProps {
  code?: string;
  title?: string;
  width?: number;
  height?: number;
  fontSize?: number;
  staggerFrames?: number;
  zoom?: number;
  speed?: number;
  className?: string;
}

const STAGE_WIDTH = 1280;
const STAGE_HEIGHT = 720;
const RING = 1;
const CHROME_HEIGHT = 40;
const BODY_PADDING_TOP = 20;
const BODY_PADDING_LEFT = 24;
const LINE_GAP = 4;
const ANCHOR_SCREEN_X = 110;
const TARGET_Y = 360;
const PULL_BACK_FRAMES = 24;

const DEFAULT_CODE = `import { AbsoluteFill } from "remotion";
import { Typewriter } from "@/components/remocn";

export function Intro() {
  return (
    <AbsoluteFill>
      <Typewriter text="Ship it" />
    </AbsoluteFill>
  );
}`;

export function GlassCodeWalk({
  code = DEFAULT_CODE,
  title = "scene.tsx",
  width = 880,
  height = 420,
  fontSize = 18,
  staggerFrames = 10,
  zoom = 2.6,
  speed = 1,
  className,
}: GlassCodeWalkProps) {
  const frame = useCurrentFrame();

  const lines = code.split("\n");
  const lineCount = lines.length;

  const blockLeft = (STAGE_WIDTH - width) / 2;
  const blockTop = (STAGE_HEIGHT - height) / 2;
  const bodyTop = blockTop + RING + CHROME_HEIGHT + BODY_PADDING_TOP;

  const lineHeightOf = (line: string) =>
    line.trim() === "" ? fontSize * 0.8 : fontSize * 1.55;

  const lineCenters: number[] = [];
  let walk = bodyTop;
  for (const line of lines) {
    const h = lineHeightOf(line);
    lineCenters.push(walk + h / 2);
    walk += h + LINE_GAP;
  }

  const anchorWorldX = blockLeft + RING + BODY_PADDING_LEFT;
  const scanStagger = staggerFrames / speed;
  const scanEnd = (lineCount - 1) * scanStagger;

  const linePosition = interpolate(frame, [0, scanEnd], [0, lineCount - 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const lower = Math.floor(linePosition);
  const upper = Math.min(lower + 1, lineCount - 1);
  const trackedY =
    lineCenters[lower] +
    (lineCenters[upper] - lineCenters[lower]) * (linePosition - lower);

  const pinnedX = ANCHOR_SCREEN_X - zoom * anchorWorldX;
  const pinnedY = TARGET_Y - zoom * trackedY;

  const pullBack = interpolate(
    frame,
    [scanEnd, scanEnd + PULL_BACK_FRAMES / speed],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.cubic),
    },
  );

  const scale = zoom + pullBack * (1 - zoom);
  const tx = (1 - pullBack) * pinnedX;
  const ty = (1 - pullBack) * pinnedY;

  return (
    <AbsoluteFill className={className} style={{ overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: STAGE_WIDTH,
          height: STAGE_HEIGHT,
          translate: `${tx}px ${ty}px`,
          scale: `${scale}`,
          transformOrigin: "0 0",
        }}
      >
        <GlassCodeBlock
          code={code}
          title={title}
          width={width}
          height={height}
          fontSize={fontSize}
          staggerFrames={staggerFrames}
          speed={speed}
        />
      </div>
    </AbsoluteFill>
  );
}

"use client";

import {
  interpolate,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export type TerminalLineType = "command" | "log" | "success" | "error";

export interface TerminalLine {
  text: string;
  type: TerminalLineType;
  delay?: number;
  /**
   * Extra freeze-frame pause AFTER this line finishes typing, in frames.
   * Use this to build dramatic tension before the next batch of logs.
   * If omitted, lines whose text ends in "..." auto-freeze for 18 frames.
   */
  pause?: number;
}

export interface TerminalSimulatorProps {
  lines?: TerminalLine[];
  prompt?: string;
  title?: string;
  background?: string;
  chromeColor?: string;
  fontSize?: number;
  /**
   * Reveal speed. Despite the name, the reveal is now CHUNKED — each
   * `1 / charsPerFrame` frames bumps the cursor by `chunkSize` characters,
   * so output appears in bursts instead of dripping char-by-char.
   */
  charsPerFrame?: number;
  /** Characters revealed per step. */
  chunkSize?: number;
  speed?: number;
  className?: string;
}

const DEFAULT_LINES: TerminalLine[] = [
  { text: "npm run build", type: "command", delay: 0 },
  { text: "Resolving dependencies...", type: "log", delay: 6 },
  { text: "> remocn@1.0.0 build", type: "log", delay: 4 },
  { text: "> next build", type: "log", delay: 4 },
  { text: "Compiling...", type: "log", delay: 12 },
  { text: "Compiled successfully in 4.2s", type: "success", delay: 14 },
  { text: "Generating static pages (24/24)", type: "log", delay: 10 },
  { text: "Build completed without errors", type: "success", delay: 12 },
];

const TYPE_COLORS: Record<TerminalLineType, string> = {
  command: "#fafafa",
  log: "#a1a1aa",
  success: "#22c55e",
  error: "#ef4444",
};

/** Auto freeze-frame heuristic: any line ending in "..." holds the camera. */
function autoPause(line: TerminalLine): number {
  if (line.pause !== undefined) return line.pause;
  if (line.text.trimEnd().endsWith("...")) return 18;
  return 0;
}

export function TerminalSimulator({
  lines = DEFAULT_LINES,
  prompt = "$",
  title = "~/projects/remocn",
  background = "#0a0a0a",
  chromeColor = "#1a1a1a",
  fontSize = 18,
  charsPerFrame = 1,
  chunkSize = 1,
  speed = 1,
  className,
}: TerminalSimulatorProps) {
  const frame = useCurrentFrame() * speed;
  const { fps } = useVideoConfig();

  const lineHeight = Math.round(fontSize * 1.6);
  const visibleLines = 8;
  const windowWidth = 900;
  const windowHeight = 480;

  // Compute cumulative start frames for each line, including auto/explicit
  // pauses AFTER a line finishes typing.
  const starts: number[] = [];
  let acc = 10;
  for (let i = 0; i < lines.length; i++) {
    const delay = lines[i].delay ?? 8;
    acc += delay;
    starts.push(acc);
    // Approximate typing duration (in frames) for chunked output.
    const typingFrames = Math.ceil(
      lines[i].text.length / (chunkSize * charsPerFrame),
    );
    acc += typingFrames + autoPause(lines[i]);
  }

  // STEP-FUNCTION scroll. Each overflowing line snaps the buffer up by
  // exactly one lineHeight on the frame it begins. No interpolation, no
  // easing — terminals do not glide.
  let translateY = 0;
  for (let i = visibleLines; i < lines.length; i++) {
    if (frame >= starts[i]) {
      translateY -= lineHeight;
    }
  }

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          width: windowWidth,
          height: windowHeight,
          background,
          borderRadius: 12,
          overflow: "hidden",
          boxShadow:
            "0 30px 80px rgba(0,0,0,0.6), 0 0 0 1px rgba(255,255,255,0.06)",
          display: "flex",
          flexDirection: "column",
          fontFamily:
            "var(--font-geist-mono), ui-monospace, SFMono-Regular, monospace",
        }}
      >
        {/* Chrome */}
        <div
          style={{
            height: 40,
            background: chromeColor,
            display: "flex",
            alignItems: "center",
            padding: "0 16px",
            gap: 8,
            borderBottom: "1px solid rgba(255,255,255,0.06)",
          }}
        >
          <Light color="#ff5f57" />
          <Light color="#febc2e" />
          <Light color="#28c840" />
          <div
            style={{
              flex: 1,
              textAlign: "center",
              color: "#71717a",
              fontSize: 13,
            }}
          >
            {title}
          </div>
        </div>

        {/* Content */}
        <div
          style={{
            flex: 1,
            padding: 20,
            overflow: "hidden",
            position: "relative",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: 20,
              right: 20,
              top: 20,
              translate: `0 ${translateY}px`,
            }}
          >
            {lines.map((line, index) => (
              <Sequence
                key={index}
                from={Math.round(starts[index] / speed)}
                layout="none"
              >
                <TerminalLineRow
                  line={line}
                  prompt={prompt}
                  fontSize={fontSize}
                  lineHeight={lineHeight}
                  charsPerFrame={charsPerFrame}
                  chunkSize={chunkSize}
                  fps={fps}
                  speed={speed}
                />
              </Sequence>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

function Light({ color }: { color: string }) {
  return (
    <div
      style={{
        width: 12,
        height: 12,
        borderRadius: "50%",
        background: color,
        opacity: 0.85,
      }}
    />
  );
}

function TerminalLineRow({
  line,
  prompt,
  fontSize,
  lineHeight,
  charsPerFrame,
  chunkSize,
  fps,
  speed,
}: {
  line: TerminalLine;
  prompt: string;
  fontSize: number;
  lineHeight: number;
  charsPerFrame: number;
  chunkSize: number;
  fps: number;
  speed: number;
}) {
  const localFrame = useCurrentFrame() * speed;
  const totalChars = line.text.length;

  // Chunked reveal: Math.floor of an interpolated count, then snapped to the
  // nearest multiple of `chunkSize`. This is what gives the bursty terminal
  // feel — text doesn't drip, it lurches.
  const linearRevealed = Math.floor(
    interpolate(localFrame, [0, totalChars / charsPerFrame], [0, totalChars], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }),
  );
  const revealed = Math.min(
    totalChars,
    Math.ceil(linearRevealed / chunkSize) * chunkSize,
  );
  const visible = line.text.substring(0, revealed);
  const typingDone = revealed >= totalChars;
  // 2 Hz blink at any framerate.
  const cursorVisible = Math.floor((localFrame / fps) * 2) % 2 === 0;

  return (
    <div
      style={{
        height: lineHeight,
        fontSize,
        color: TYPE_COLORS[line.type],
        display: "flex",
        alignItems: "center",
        whiteSpace: "pre",
      }}
    >
      {line.type === "command" && (
        <span style={{ color: "#22c55e", marginRight: 8 }}>{prompt}</span>
      )}
      <span>{visible}</span>
      {!typingDone && cursorVisible && (
        <span
          style={{
            display: "inline-block",
            width: fontSize * 0.55,
            height: fontSize,
            background: TYPE_COLORS[line.type],
            marginLeft: 2,
          }}
        />
      )}
    </div>
  );
}

"use client";

import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";

import { TerminalSimulator } from "@/components/remocn/terminal-simulator";

export interface TerminalCursorZoomProps {
  command?: string;
  zoom?: number;
  fontSize?: number;
  prompt?: string;
  title?: string;
  charsPerFrame?: number;
  chunkSize?: number;
  speed?: number;
  className?: string;
}

const STAGE_WIDTH = 1280;
const STAGE_HEIGHT = 720;
const WINDOW_WIDTH = 900;
const WINDOW_HEIGHT = 480;
const CONTENT_PADDING = 20;
const CHROME_HEIGHT = 40;
const PROMPT_GAP = 8;
const FIRST_LINE_FRAME = 10;

export function TerminalCursorZoom({
  command = "npx shadcn add @remocn/terminal-cursor-zoom",
  zoom = 2.8,
  fontSize = 20,
  prompt = "$",
  title = "~/code/remocn-demo",
  charsPerFrame = 1,
  chunkSize = 1,
  speed = 1,
  className,
}: TerminalCursorZoomProps) {
  const frame = useCurrentFrame();

  const charWidth = fontSize * 0.6;
  const windowLeft = (STAGE_WIDTH - WINDOW_WIDTH) / 2;
  const windowTop = (STAGE_HEIGHT - WINDOW_HEIGHT) / 2;
  const textStartX =
    windowLeft + CONTENT_PADDING + prompt.length * charWidth + PROMPT_GAP;
  const lineHeight = Math.round(fontSize * 1.6);
  const cursorY = windowTop + CHROME_HEIGHT + CONTENT_PADDING + lineHeight / 2;

  const lineStart = Math.round(FIRST_LINE_FRAME / speed);
  const localFrame = (frame - lineStart) * speed;
  const linearRevealed = Math.floor(
    interpolate(
      localFrame,
      [0, command.length / charsPerFrame],
      [0, command.length],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      },
    ),
  );
  const revealed = Math.min(
    command.length,
    Math.ceil(linearRevealed / chunkSize) * chunkSize,
  );

  const cursorX = textStartX + revealed * charWidth;
  const tx = STAGE_WIDTH / 2 - zoom * cursorX;
  const ty = STAGE_HEIGHT / 2 - zoom * cursorY;

  return (
    <AbsoluteFill className={className} style={{ overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: STAGE_WIDTH,
          height: STAGE_HEIGHT,
          translate: `${tx}px ${ty}px`,
          scale: `${zoom}`,
          transformOrigin: "0 0",
        }}
      >
        <TerminalSimulator
          lines={[{ text: command, type: "command", delay: 0 }]}
          prompt={prompt}
          title={title}
          fontSize={fontSize}
          charsPerFrame={charsPerFrame}
          chunkSize={chunkSize}
          speed={speed}
        />
      </div>
    </AbsoluteFill>
  );
}

"use client";

import { spring, useCurrentFrame, useVideoConfig } from "remotion";

export interface AnimatedLineChartProps {
  data?: number[];
  width?: number;
  height?: number;
  strokeColor?: string;
  strokeWidth?: number;
  gridColor?: string;
  showDot?: boolean;
  speed?: number;
  className?: string;
}

export function AnimatedLineChart({
  data = [12, 19, 8, 15, 22, 18, 28, 25, 32],
  width = 1000,
  height = 500,
  strokeColor = "#22c55e",
  strokeWidth = 4,
  gridColor = "#27272a",
  showDot = true,
  speed = 1,
  className,
}: AnimatedLineChartProps) {
  const frame = useCurrentFrame() * speed;
  const { fps, durationInFrames } = useVideoConfig();

  const padding = 60;
  const innerWidth = width - padding * 2;
  const innerHeight = height - padding * 2;

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;

  const points = data.map((value, index) => {
    const x = padding + (index / (data.length - 1)) * innerWidth;
    const y = padding + innerHeight - ((value - min) / range) * innerHeight;
    return { x, y };
  });

  // Analytical path length: sum of segment distances
  let pathLength = 0;
  for (let i = 1; i < points.length; i++) {
    const dx = points[i].x - points[i - 1].x;
    const dy = points[i].y - points[i - 1].y;
    pathLength += Math.sqrt(dx * dx + dy * dy);
  }

  const d = points
    .map((p, i) => `${i === 0 ? "M" : "L"}${p.x.toFixed(2)},${p.y.toFixed(2)}`)
    .join(" ");

  // Spring-driven progress: smooth, no bounce. Matches the "smooth" preset
  // from remotion-best-practices/timing.md.
  const progress = spring({
    frame,
    fps,
    durationInFrames: Math.round(durationInFrames * 0.85),
    config: { damping: 200 },
  });

  const dashOffset = pathLength * (1 - progress);

  // Find dot position along the path at current progress
  const targetLen = pathLength * progress;
  let traveled = 0;
  let dotX = points[0].x;
  let dotY = points[0].y;
  for (let i = 1; i < points.length; i++) {
    const dx = points[i].x - points[i - 1].x;
    const dy = points[i].y - points[i - 1].y;
    const segLen = Math.sqrt(dx * dx + dy * dy);
    if (traveled + segLen >= targetLen) {
      const t = (targetLen - traveled) / segLen;
      dotX = points[i - 1].x + dx * t;
      dotY = points[i - 1].y + dy * t;
      break;
    }
    traveled += segLen;
    dotX = points[i].x;
    dotY = points[i].y;
  }

  const gridRows = 4;
  const gridCols = data.length - 1;

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
      }}
    >
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ overflow: "visible" }}
      >
        {/* Horizontal grid */}
        {Array.from({ length: gridRows + 1 }).map((_, i) => {
          const y = padding + (i / gridRows) * innerHeight;
          return (
            <line
              key={`h-${i}`}
              x1={padding}
              x2={padding + innerWidth}
              y1={y}
              y2={y}
              stroke={gridColor}
              strokeWidth={1}
            />
          );
        })}
        {/* Vertical grid */}
        {Array.from({ length: gridCols + 1 }).map((_, i) => {
          const x = padding + (i / gridCols) * innerWidth;
          return (
            <line
              key={`v-${i}`}
              x1={x}
              x2={x}
              y1={padding}
              y2={padding + innerHeight}
              stroke={gridColor}
              strokeWidth={1}
            />
          );
        })}
        {/* Axis */}
        <line
          x1={padding}
          x2={padding}
          y1={padding}
          y2={padding + innerHeight}
          stroke={gridColor}
          strokeWidth={2}
        />
        <line
          x1={padding}
          x2={padding + innerWidth}
          y1={padding + innerHeight}
          y2={padding + innerHeight}
          stroke={gridColor}
          strokeWidth={2}
        />

        {/* Animated line */}
        <path
          d={d}
          fill="none"
          stroke={strokeColor}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={pathLength}
          strokeDashoffset={dashOffset}
          style={{
            filter: `drop-shadow(0 0 12px ${strokeColor}55)`,
          }}
        />

        {showDot && progress > 0 && progress < 1 && (
          <circle
            cx={dotX}
            cy={dotY}
            r={strokeWidth * 2}
            fill={strokeColor}
            style={{
              filter: `drop-shadow(0 0 8px ${strokeColor})`,
            }}
          />
        )}
      </svg>
    </div>
  );
}

"use client";

import { spring, useCurrentFrame, useVideoConfig } from "remotion";

export interface AnimatedBarChartProps {
  data?: number[];
  labels?: string[];
  width?: number;
  height?: number;
  barColor?: string;
  gap?: number;
  staggerFrames?: number;
  speed?: number;
  className?: string;
}

export function AnimatedBarChart({
  data = [35, 60, 45, 80, 55, 70, 90, 65],
  labels,
  width = 1000,
  height = 500,
  barColor = "#0ea5e9",
  gap = 16,
  staggerFrames = 6,
  speed = 1,
  className,
}: AnimatedBarChartProps) {
  const frame = useCurrentFrame() * speed;
  const { fps } = useVideoConfig();

  const padding = 60;
  const labelSpace = labels ? 40 : 0;
  const innerWidth = width - padding * 2;
  const innerHeight = height - padding * 2 - labelSpace;
  const max = Math.max(...data);
  const barWidth = (innerWidth - gap * (data.length - 1)) / data.length;
  const baseY = padding + innerHeight;

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
      }}
    >
      <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
        {/* Baseline */}
        <line
          x1={padding}
          x2={padding + innerWidth}
          y1={baseY}
          y2={baseY}
          stroke="#27272a"
          strokeWidth={2}
        />

        {data.map((value, index) => {
          const targetHeight = (value / max) * innerHeight;
          const x = padding + index * (barWidth + gap);
          const y = baseY - targetHeight;

          const scaleY = spring({
            frame: frame - index * staggerFrames,
            fps,
            config: { damping: 12, stiffness: 100, mass: 0.8 },
            from: 0,
            to: 1,
          });

          return (
            <g key={index}>
              <rect
                x={x}
                y={y}
                width={barWidth}
                height={targetHeight}
                rx={6}
                fill={barColor}
                style={{
                  scale: `1 ${scaleY}`,
                  transformOrigin: `${x + barWidth / 2}px ${baseY}px`,
                  transformBox: "fill-box",
                  filter: `drop-shadow(0 4px 16px ${barColor}55)`,
                }}
              />
              {labels?.[index] && (
                <text
                  x={x + barWidth / 2}
                  y={baseY + 28}
                  fill="#a1a1aa"
                  fontSize={16}
                  textAnchor="middle"
                  style={{
                    opacity: scaleY,
                    fontFamily:
                      "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
                  }}
                >
                  {labels[index]}
                </text>
              )}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

