import type React from "react";
import { useCurrentFrame } from "remotion";
import {
  DEFAULT_STEP,
  hashRange,
  paperJitter,
  steppedRamp,
} from "@/lib/remocn/stop-motion";

export interface PaperStickerProps {
  children: React.ReactNode;
  at?: number;
  seed?: string;
  padding?: string;
  background?: string;
  borderColor?: string;
  maxTilt?: number;
  step?: number;
}

export function PaperSticker({
  children,
  at = 0,
  seed = "sticker",
  padding = "10px 16px",
  background = "#fbfaf6",
  borderColor = "rgba(38,36,44,0.55)",
  maxTilt = 2.6,
  step = DEFAULT_STEP,
}: PaperStickerProps) {
  const frame = useCurrentFrame();
  const progress = steppedRamp(frame, at, at + 2 * step, { step });
  if (progress === 0) return null;

  const tilt = hashRange(`${seed}:rot`, -maxTilt, maxTilt);
  const jitter = paperJitter(frame, `sticker:${seed}`, {
    amp: 0.7,
    rotAmp: 0.2,
    step,
  });

  return (
    <div
      style={{
        display: "inline-block",
        padding,
        background,
        border: `1px solid ${borderColor}`,
        borderRadius: 3,
        boxShadow: "0 2px 5px rgba(38,36,44,0.14)",
        translate: `${jitter.x}px ${jitter.y}px`,
        rotate: `${tilt + jitter.rot}deg`,
        scale: `${progress < 1 ? 1.12 : 1}`,
      }}
    >
      {children}
    </div>
  );
}

"use client";

import type React from "react";
import { Handwrite } from "@/components/remocn/handwrite";
import { DEFAULT_STEP } from "@/lib/remocn/stop-motion";

const BASE_WIDTH = 652;
const BASE_PAD = 16;
const BASE_MEDIA_WIDTH = 620;
const BASE_MEDIA_HEIGHT = 349;
const BASE_CAPTION_HEIGHT = 62;
const BASE_CAPTION_SIZE = 36;

export type PolaroidGeometry = {
  pad: number;
  mediaWidth: number;
  mediaHeight: number;
  captionHeight: number;
  height: number;
};

export function polaroidGeometry(width: number): PolaroidGeometry {
  const scale = width / BASE_WIDTH;
  const pad = BASE_PAD * scale;
  const mediaWidth = BASE_MEDIA_WIDTH * scale;
  const mediaHeight = BASE_MEDIA_HEIGHT * scale;
  const captionHeight = BASE_CAPTION_HEIGHT * scale;
  return {
    pad,
    mediaWidth,
    mediaHeight,
    captionHeight,
    height: pad + mediaHeight + captionHeight,
  };
}

export interface PolaroidProps {
  children: React.ReactNode;
  caption?: string;
  captionAt?: number;
  width?: number;
  frameColor?: string;
  captionColor?: string;
  captionSize?: number;
  step?: number;
}

export function Polaroid({
  children,
  caption,
  captionAt = 0,
  width = BASE_WIDTH,
  frameColor = "#fdfcf8",
  captionColor = "#26242c",
  captionSize,
  step = DEFAULT_STEP,
}: PolaroidProps) {
  const { pad, mediaWidth, mediaHeight, captionHeight, height } =
    polaroidGeometry(width);
  const resolvedCaptionSize =
    captionSize ?? BASE_CAPTION_SIZE * (width / BASE_WIDTH);

  return (
    <div
      style={{
        width,
        height,
        boxSizing: "border-box",
        background: frameColor,
        borderRadius: 4,
        boxShadow:
          "0 8px 20px rgba(38,36,44,0.18), 0 2px 5px rgba(38,36,44,0.12)",
        paddingTop: pad,
      }}
    >
      <div
        style={{
          position: "relative",
          width: mediaWidth,
          height: mediaHeight,
          margin: "0 auto",
          background: "#100f14",
          overflow: "hidden",
        }}
      >
        {children}
      </div>
      <div style={{ position: "relative", height: captionHeight }}>
        {caption ? (
          <Handwrite
            text={caption}
            fontSize={resolvedCaptionSize}
            color={captionColor}
            delay={captionAt}
            perStep={1.4}
            weight={600}
            step={step}
          />
        ) : null}
      </div>
    </div>
  );
}

"use client";

import { useCurrentFrame } from "remotion";
import { Handwrite, handwriteDuration } from "@/components/remocn/handwrite";
import { DEFAULT_STEP, hashRange, steppedRamp } from "@/lib/remocn/stop-motion";

const easeOutCubic = (t: number) => 1 - (1 - t) ** 3;

const DEFAULT_PER_STEP = 1.6;

export type CheckListItem = {
  text: string;
  checked?: boolean;
};

export type CheckListEntry = {
  text: string;
  checked: boolean;
};

export type CheckListGeometry = {
  boxSize: number;
  boxGap: number;
  rowHeight: number;
  labelWidth: number;
};

export type CheckListBeat = {
  boxFrom: number;
  boxTo: number;
  labelAt: number;
  labelEnd: number;
  tickFrom?: number;
  tickTo?: number;
  strikeFrom?: number;
  strikeTo?: number;
};

export type CheckListTiming = {
  delay?: number;
  itemGap?: number;
  perStep?: number;
  step?: number;
  closeGap?: number;
};

export function normalizeCheckListItems(
  items: (string | CheckListItem)[],
): CheckListEntry[] {
  return items.map((item) =>
    typeof item === "string"
      ? { text: item, checked: true }
      : { text: item.text, checked: item.checked ?? true },
  );
}

export function checkListGeometry(
  width: number,
  fontSize: number,
): CheckListGeometry {
  const boxSize = Math.round(fontSize * 0.62);
  const boxGap = Math.round(fontSize * 0.4);
  return {
    boxSize,
    boxGap,
    rowHeight: Math.round(fontSize * 1.15),
    labelWidth: Math.max(fontSize * 2, width - boxSize - boxGap),
  };
}

export function checkListRowWidth(width: number, fontSize: number): number {
  const { boxSize, boxGap, labelWidth } = checkListGeometry(width, fontSize);
  return boxSize + boxGap + labelWidth;
}

export function checkListEnterEnd(
  items: (string | CheckListItem)[],
  options?: CheckListTiming,
): number {
  const step = options?.step ?? DEFAULT_STEP;
  const delay = options?.delay ?? 0;
  const itemGap = options?.itemGap ?? step * 6;
  const perStep = options?.perStep ?? DEFAULT_PER_STEP;

  return normalizeCheckListItems(items).reduce(
    (end, item, i) =>
      Math.max(
        end,
        delay +
          i * itemGap +
          step * 2 +
          handwriteDuration(item.text, { perStep, step }),
      ),
    delay,
  );
}

export function checkListSchedule(
  items: (string | CheckListItem)[],
  options?: CheckListTiming,
): CheckListBeat[] {
  const step = options?.step ?? DEFAULT_STEP;
  const delay = options?.delay ?? 0;
  const itemGap = options?.itemGap ?? step * 6;
  const perStep = options?.perStep ?? DEFAULT_PER_STEP;
  const closeGap = options?.closeGap ?? step * 3;
  const entries = normalizeCheckListItems(items);
  const enterEnd = checkListEnterEnd(entries, options);

  const closeOrder = new Map<number, number>();
  entries.forEach((item, i) => {
    if (item.checked) {
      closeOrder.set(i, closeOrder.size);
    }
  });

  return entries.map((item, i) => {
    const boxFrom = delay + i * itemGap;
    const boxTo = boxFrom + step * 2;
    const labelEnd = boxTo + handwriteDuration(item.text, { perStep, step });
    const slot = closeOrder.get(i);
    if (slot === undefined) {
      return { boxFrom, boxTo, labelAt: boxTo, labelEnd };
    }
    const tickFrom = enterEnd + slot * closeGap;
    const tickTo = tickFrom + step * 2;
    return {
      boxFrom,
      boxTo,
      labelAt: boxTo,
      labelEnd,
      tickFrom,
      tickTo,
      strikeFrom: tickTo,
      strikeTo: tickTo + step * 2,
    };
  });
}

export function checkListDuration(
  items: (string | CheckListItem)[],
  options?: CheckListTiming,
): number {
  return checkListSchedule(items, options).reduce(
    (end, beat) => Math.max(end, beat.strikeTo ?? beat.labelEnd),
    0,
  );
}

const boxPath = (size: number, seed: string, index: number): string => {
  const nudge = (n: number) => hashRange(`${seed}:${index}:c${n}`, -1.5, 1.5);
  const lo = size * 0.08;
  const hi = size - lo;
  const corners: [number, number][] = [
    [lo + nudge(0), lo + nudge(1)],
    [hi + nudge(2), lo + nudge(3)],
    [hi + nudge(4), hi + nudge(5)],
    [lo + nudge(6), hi + nudge(7)],
  ];
  const [start, ...rest] = corners;
  return `M ${start[0]} ${start[1]} ${rest
    .map(([x, y]) => `L ${x} ${y}`)
    .join(" ")} Z`;
};

const tickPath = (size: number): string =>
  `M ${size * 0.2} ${size * 0.52} L ${size * 0.42} ${size * 0.78} L ${size * 0.88} ${size * 0.14}`;

const CAVEAT_ADVANCE = 0.36;

export function checkListStrikeWidth(
  text: string,
  fontSize: number,
  labelWidth: number,
): number {
  return Math.min(
    labelWidth,
    Array.from(text).length * fontSize * CAVEAT_ADVANCE,
  );
}

const strikePath = (
  reach: number,
  fontSize: number,
  rowHeight: number,
  seed: string,
  index: number,
): string => {
  const lift = (n: number) => hashRange(`${seed}:${index}:s${n}`, -1.6, 1.6);
  const overshoot = fontSize * 0.07;
  const mid = rowHeight / 2;
  return `M ${-overshoot} ${mid + lift(0)} C ${reach * 0.35} ${mid + lift(1)}, ${reach * 0.7} ${mid + lift(2)}, ${reach + overshoot} ${mid + lift(3)}`;
};

export interface CheckListProps {
  items: (string | CheckListItem)[];
  width: number;
  fontSize?: number;
  color?: string;
  boxColor?: string;
  tickColor?: string;
  delay?: number;
  itemGap?: number;
  closeGap?: number;
  rowGap?: number;
  strokeWidth?: number;
  perStep?: number;
  weight?: 400 | 500 | 600 | 700;
  seed?: string;
  step?: number;
}

export function CheckList({
  items,
  width,
  fontSize = 40,
  color = "#26242c",
  boxColor = "#26242c",
  tickColor = "#6f7f35",
  delay = 0,
  itemGap,
  closeGap,
  rowGap,
  strokeWidth = 3,
  perStep = DEFAULT_PER_STEP,
  weight = 600,
  seed = "checklist",
  step = DEFAULT_STEP,
}: CheckListProps) {
  const frame = useCurrentFrame();
  const entries = normalizeCheckListItems(items);
  const schedule = checkListSchedule(entries, {
    delay,
    itemGap,
    closeGap,
    perStep,
    step,
  });
  const { boxSize, boxGap, rowHeight, labelWidth } = checkListGeometry(
    width,
    fontSize,
  );

  return (
    <div
      style={{
        width: checkListRowWidth(width, fontSize),
        display: "flex",
        flexDirection: "column",
        gap: rowGap ?? fontSize * 0.55,
      }}
    >
      {entries.map((item, i) => {
        const beat = schedule[i];
        const boxProgress = steppedRamp(frame, beat.boxFrom, beat.boxTo, {
          ease: easeOutCubic,
          step,
        });
        const tickProgress =
          beat.tickFrom === undefined || beat.tickTo === undefined
            ? 0
            : steppedRamp(frame, beat.tickFrom, beat.tickTo, {
                ease: easeOutCubic,
                step,
              });
        const strikeProgress =
          beat.strikeFrom === undefined || beat.strikeTo === undefined
            ? 0
            : steppedRamp(frame, beat.strikeFrom, beat.strikeTo, {
                ease: easeOutCubic,
                step,
              });

        return (
          <div
            key={`${item.text}:${i}`}
            style={{
              display: "flex",
              alignItems: "center",
              gap: boxGap,
              height: rowHeight,
            }}
          >
            <svg
              width={boxSize}
              height={boxSize}
              viewBox={`0 0 ${boxSize} ${boxSize}`}
              style={{ display: "block", overflow: "visible", flexShrink: 0 }}
            >
              <path
                d={boxPath(boxSize, seed, i)}
                stroke={boxColor}
                strokeWidth={strokeWidth}
                strokeLinecap="round"
                strokeLinejoin="round"
                fill="none"
                pathLength={1}
                strokeDasharray={1}
                strokeDashoffset={1 - boxProgress}
                opacity={boxProgress > 0 ? 0.9 : 0}
              />
              {item.checked ? (
                <path
                  d={tickPath(boxSize)}
                  stroke={tickColor}
                  strokeWidth={strokeWidth + 1}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  fill="none"
                  pathLength={1}
                  strokeDasharray={1}
                  strokeDashoffset={1 - tickProgress}
                  opacity={tickProgress > 0 ? 1 : 0}
                />
              ) : null}
            </svg>
            <div
              style={{
                position: "relative",
                flexShrink: 0,
                width: labelWidth,
                height: rowHeight,
              }}
            >
              <Handwrite
                text={item.text}
                fontSize={fontSize}
                color={color}
                delay={beat.labelAt}
                perStep={perStep}
                weight={weight}
                align="left"
                step={step}
              />
              {item.checked ? (
                <svg
                  width={labelWidth}
                  height={rowHeight}
                  viewBox={`0 0 ${labelWidth} ${rowHeight}`}
                  style={{
                    position: "absolute",
                    inset: 0,
                    display: "block",
                    overflow: "visible",
                  }}
                >
                  <path
                    d={strikePath(
                      checkListStrikeWidth(item.text, fontSize, labelWidth),
                      fontSize,
                      rowHeight,
                      seed,
                      i,
                    )}
                    stroke={tickColor}
                    strokeWidth={strokeWidth}
                    strokeLinecap="round"
                    fill="none"
                    pathLength={1}
                    strokeDasharray={1}
                    strokeDashoffset={1 - strikeProgress}
                    opacity={strikeProgress > 0 ? 0.85 : 0}
                  />
                </svg>
              ) : null}
            </div>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import {
  AbsoluteFill,
  Easing,
  Img,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};
const EASE_OUT = Easing.out(Easing.cubic);

export type ReelProps = {
  images: string[];
  width?: number;
  height?: number;
  radius?: number;
  step?: number;
  reveal?: number;
  objectPosition?: string;
  background?: string;
};

export function Reel({
  images,
  width = 1180,
  height = 676,
  radius = 16,
  step = 20,
  reveal = 13,
  objectPosition = "top",
  background = "#050506",
}: ReelProps) {
  const frame = useCurrentFrame();
  const { width: compWidth, height: compHeight } = useVideoConfig();
  const left = (compWidth - width) / 2;
  const top = (compHeight - height) / 2;

  return (
    <AbsoluteFill>
      {images.map((src, i) => {
        const p = interpolate(frame, [i * step, i * step + reveal], [0, 1], {
          ...clamp,
          easing: EASE_OUT,
        });
        if (p <= 0) return null;
        const inset = (1 - p) * 50;
        const imgScale = interpolate(p, [0, 1], [1.08, 1], clamp);
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left,
              top,
              width,
              height,
              zIndex: i,
              clipPath: `inset(${inset}% ${inset}% round ${radius}px)`,
              WebkitClipPath: `inset(${inset}% ${inset}% round ${radius}px)`,
              background,
              boxShadow: "0 30px 80px rgba(0,0,0,0.6)",
              willChange: "clip-path",
            }}
          >
            <Img
              src={src}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                objectPosition,
                scale: `${imgScale}`,
                willChange: "transform",
              }}
            />
            <div
              style={{
                position: "absolute",
                inset: 0,
                borderRadius: radius,
                border: "1px solid rgba(255,255,255,0.08)",
              }}
            />
          </div>
        );
      })}
    </AbsoluteFill>
  );
}
